package com.ardougnehelper;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup("ardougnenext")
public interface ArdougneConfig extends Config
{
    @ConfigSection(
        name = "Obstacle Settings",
        description = "Appearance of the current obstacle's clickable hull.",
        position = 0,
        closedByDefault = false
    )
    String obstacleSettings = "obstacleSettings";

    @ConfigSection(
        name = "Preview Settings",
        description = "Appearance of the next obstacle's projected hull. The preview appears after a valid click and movement.",
        position = 1,
        closedByDefault = true
    )
    String previewSettings = "previewSettings";

    @ConfigSection(
        name = "Marks of Grace",
        description = "Mark highlighting and optional obstacle-priority behavior.",
        position = 2,
        closedByDefault = true
    )
    String marksSettings = "marksSettings";

    @ConfigSection(
        name = "HUD Settings",
        description = "Control the compact course counter panel.",
        position = 3,
        closedByDefault = true
    )
    String hudSettings = "hudSettings";

    // Obstacle Settings
    @ConfigItem(keyName = "hullColor", name = "Obstacle hull color",
        description = "Color of the current obstacle hull", position = 0, section = obstacleSettings)
    default Color hullColor() { return Color.CYAN; }

    @Range(min = 0, max = 255)
    @ConfigItem(keyName = "fillAlpha", name = "Fill opacity",
        description = "Fill alpha (0 to 255) for the live obstacle and ground marks", position = 1, section = obstacleSettings)
    default int fillAlpha() { return 35; }

    // Preview Settings
    @ConfigItem(keyName = "showGhostPreview", name = "Next obstacle preview",
        description = "After interacting with the highlighted obstacle and starting to move, show the next obstacle's projected hull. Only one obstacle hull is shown at a time.",
        position = 0, section = previewSettings)
    default boolean showGhostPreview() { return true; }

    @ConfigItem(keyName = "ghostColor", name = "Preview hull color",
        description = "Color of the solid predicted clickbox outline", position = 1, section = previewSettings)
    default Color ghostColor() { return Color.ORANGE; }

    @Range(min = 0, max = 255)
    @ConfigItem(keyName = "ghostFillAlpha", name = "Preview fill opacity",
        description = "Opacity of the projected hull fill", position = 2, section = previewSettings)
    default int ghostFillAlpha() { return 25; }

    // Marks of Grace
    @ConfigItem(keyName = "highlightMarks", name = "Highlight Marks of Grace",
        description = "Highlight ground marks while continuing to highlight the next obstacle", position = 0, section = marksSettings)
    default boolean highlightMarks() { return true; }

    @ConfigItem(keyName = "markColor", name = "Mark highlight color",
        description = "Color for ground tiles containing Marks of Grace", position = 1, section = marksSettings)
    default Color markColor() { return Color.MAGENTA; }

    @Range(min = 1, max = 20)
    @ConfigItem(keyName = "minimumGroundMarks", name = "Highlight threshold",
        description = "Minimum number of ground Marks of Grace needed before highlighting them (1 to 20); the HUD still counts all detected marks",
        position = 2, section = marksSettings)
    default int minimumGroundMarks() { return 1; }

    @ConfigItem(keyName = "prioritizeMarks", name = "Prioritize Marks of Grace",
        description = "When obstacle 3 is activated and enough Marks are present, temporarily hide both obstacle hulls and collect Marks before obstacle 4. With no qualifying Marks, normal previews remain visible. Off preserves existing behavior.",
        position = 3, section = marksSettings)
    default boolean prioritizeMarks() { return false; }

    // HUD Settings
    @ConfigItem(keyName = "enableHud", name = "Enable HUD",
        description = "Display ground mark and lap/fall counters while at the Ardougne course", position = 0, section = hudSettings)
    default boolean enableHud() { return true; }

    @Range(min = 0, max = 255)
    @ConfigItem(keyName = "hudBackgroundOpacity", name = "Background opacity",
        description = "HUD background alpha: 0 = invisible, 255 = solid", position = 1, section = hudSettings)
    default int hudBackgroundOpacity() { return 156; }

    // Retain the old key to preserve existing 'Show laps' preferences.
    @ConfigItem(keyName = "showRunCounters", name = "Show laps",
        description = "Show completed laps during this session", position = 2, section = hudSettings)
    default boolean showRunCounters() { return true; }

    // Use a new key so users upgrading from previous builds (where falls
    // defaulted on) also start with this optional line disabled.
    @ConfigItem(keyName = "showFallCount", name = "Show falls",
        description = "Show a separate confirmed-falls counter in the HUD", position = 3, section = hudSettings)
    default boolean showFallCount() { return false; }

    @ConfigItem(keyName = "friendlyTaunt", name = "Friendly taunt",
        description = "Show Don't give up! on the ground, Isn't this fun? while stationary on rooftops, or yellow I believe in you! during walking and obstacle animations",
        position = 4, section = hudSettings)
    default boolean friendlyTaunt() { return false; }
}

package com.ardougnehelper;

/**
 * Pure state tracking for the seven Ardougne rooftop obstacles. It deliberately
 * does not infer a successful lap or fall from a click/animation alone.
 *
 * A lap needs the final obstacle's XP reward. A fall needs confirmed rooftop
 * progress followed by three consecutive ground-level game ticks. Landing at
 * the course's known finish without receiving the final XP is considered
 * unverified (not a fall). This favors accurate counters over guessing.
 */
final class ArdougneCourseTracker
{
    enum Event
    {
        NONE, ADVANCED, LAP, FALL, RECOVERED, INTERRUPTED, UNVERIFIED_FINISH
    }

    static final int[] OBSTACLE_XP = {43, 65, 50, 21, 28, 57, 625};
    static final int STAGE_COUNT = OBSTACLE_XP.length;
    static final int FALL_CONFIRM_TICKS = 3;
    static final int FINISH_CONFIRM_TICKS = 6;
    static final int COURSE_FINISH_X = 2668;
    static final int COURSE_FINISH_Y = 3297;
    private static final int FINISH_RADIUS = 5;
    private static final int MAX_PLAUSIBLE_FALL_DISTANCE = 18;

    private int stage = -1;
    private int laps;
    private int falls;
    private int groundTicks;
    private int lastRooftopX;
    private int lastRooftopY;
    private boolean hasLastRooftopPosition;
    private boolean visitedRooftop;
    private boolean activeRun;

    int getStage() { return stage; }
    int getLaps() { return laps; }
    int getFalls() { return falls; }

    /** Reset stage across a scene load or login, without erasing session totals. */
    Event onSceneLoading()
    {
        boolean interrupted = activeRun;
        clearRun(-1);
        return interrupted ? Event.INTERRUPTED : Event.NONE;
    }

    void clearSession()
    {
        clearRun(-1);
        laps = 0;
        falls = 0;
    }

    /**
     * Called once each game tick, after any movement for the tick. The inferred
     * stage is a fallback estimate from nearby objects (or -1 if unknown).
     */
    Event onPosition(boolean inRegion, int x, int y, int plane, int inferredStage)
    {
        if (!inRegion)
        {
            boolean interrupted = activeRun;
            clearRun(-1);
            return interrupted ? Event.INTERRUPTED : Event.NONE;
        }

        if (stage < 0)
        {
            if (plane == 0)
            {
                stage = 0;
            }
            else if (validStage(inferredStage))
            {
                stage = inferredStage;
                activeRun = stage > 0;
                visitedRooftop = true;
                rememberRooftop(x, y);
                return Event.RECOVERED;
            }
        }

        if (plane > 0)
        {
            visitedRooftop = true;
            rememberRooftop(x, y);
            groundTicks = 0;
            // If XP tracking was initialized too late, recover from the visible
            // location instead of permanently highlighting the starting beams.
            if (stage == 0 && !activeRun && validStage(inferredStage) && inferredStage > 0)
            {
                stage = inferredStage;
                activeRun = true;
                return Event.RECOVERED;
            }
            return Event.NONE;
        }

        if (stage < 1 || !activeRun)
        {
            groundTicks = 0;
            stage = 0;
            return Event.NONE;
        }

        // A teleport within the same map region can change floors instantly.
        // Don't mistake a large horizontal jump for falling off an obstacle.
        if (hasLastRooftopPosition &&
            (Math.abs(x - lastRooftopX) > MAX_PLAUSIBLE_FALL_DISTANCE ||
             Math.abs(y - lastRooftopY) > MAX_PLAUSIBLE_FALL_DISTANCE))
        {
            clearRun(0);
            return Event.INTERRUPTED;
        }

        if (!visitedRooftop)
        {
            // A first-obstacle XP event may arrive before a rooftop position
            // is sampled. Do not claim a fall without observing the roof.
            clearRun(0);
            return Event.INTERRUPTED;
        }

        groundTicks++;

        if (stage == STAGE_COUNT - 1 && nearFinish(x, y))
        {
            // The final obstacle transitions to the ground. The final XP can
            // arrive after the position update, so give it time to arrive.
            if (groundTicks >= FINISH_CONFIRM_TICKS)
            {
                clearRun(0);
                return Event.UNVERIFIED_FINISH;
            }
            return Event.NONE;
        }

        if (groundTicks >= FALL_CONFIRM_TICKS)
        {
            falls++;
            clearRun(0);
            return Event.FALL;
        }
        return Event.NONE;
    }

    /**
     * Called only for a *new* positive Agility XP delta. Each course obstacle
     * awards a distinct amount, permitting recovery if a previous XP event was
     * missed or the inferred stage was wrong.
     */
    Event onExperienceGain(int gain, boolean inRegion, int plane)
    {
        if (!inRegion || gain <= 0)
        {
            return Event.NONE;
        }
        int completed = stageForExperience(gain);
        if (completed < 0)
        {
            return Event.NONE;
        }

        // Reject a repeated/older event or arbitrary off-course XP. The final
        // obstacle can award its XP after the player lands on plane 0.
        if (stage >= 0 && completed < stage)
        {
            return Event.NONE;
        }
        if (completed > 0 && completed != stage && !visitedRooftop && plane == 0)
        {
            return Event.NONE;
        }

        groundTicks = 0;
        if (completed == STAGE_COUNT - 1)
        {
            laps++;
            clearRun(0);
            return Event.LAP;
        }

        stage = completed + 1;
        activeRun = true;
        if (plane > 0)
        {
            visitedRooftop = true;
        }
        return Event.ADVANCED;
    }

    private static boolean validStage(int candidate)
    {
        return candidate >= 0 && candidate < STAGE_COUNT;
    }

    private static boolean nearFinish(int x, int y)
    {
        return Math.abs(x - COURSE_FINISH_X) <= FINISH_RADIUS
            && Math.abs(y - COURSE_FINISH_Y) <= FINISH_RADIUS;
    }

    private static int stageForExperience(int gain)
    {
        for (int i = 0; i < OBSTACLE_XP.length; i++)
        {
            if (OBSTACLE_XP[i] == gain)
            {
                return i;
            }
        }
        return -1;
    }

    private void rememberRooftop(int x, int y)
    {
        lastRooftopX = x;
        lastRooftopY = y;
        hasLastRooftopPosition = true;
    }

    private void clearRun(int newStage)
    {
        stage = newStage;
        activeRun = false;
        visitedRooftop = false;
        groundTicks = 0;
        hasLastRooftopPosition = false;
    }
}

package com.ardougnehelper;

/**
 * HUD-only acknowledgment for obstacle 1 when position-based stage recovery
 * outruns the 43 XP event. This class NEVER advances the course tracker,
 * changes preview eligibility, or authorizes obstacle interactions.
 *
 * A fallback needs a valid obstacle-1 click on ground level, a subsequent
 * rooftop arrival, the *exact* 43 XP delta, and the course tracker already
 * displaying obstacle 2. It is one-shot, expires, and resets on interruption.
 */
final class ArdougneFirstObstacleHudXp
{
    static final int FIRST_OBSTACLE_XP = ArdougneCourseTracker.OBSTACLE_XP[0];
    static final long MAX_CLICK_TO_XP_NANOS = 15_000_000_000L;
    private boolean armed;
    private long clickedAtNanos;
    private boolean reachedRoof;

    void reset()
    {
        armed = false;
        clickedAtNanos = 0;
        reachedRoof = false;
    }

    /** Called only after the plugin has validated the menu target and action. */
    void onValidObstacleClick(int stage, int plane, long nowNanos)
    {
        if (stage != 0 || plane != 0)
        {
            reset();
            return;
        }
        armed = true;
        clickedAtNanos = nowNanos;
        reachedRoof = false;
    }

    /** Observe the real plane; position-based recovery to stage 1 is allowed. */
    void observe(boolean inRegion, int stage, int plane, long nowNanos)
    {
        if (!armed) { return; }
        if (!inRegion || stage < 0 || stage > 1 || plane < 0 || plane > 3 ||
            expired(nowNanos))
        {
            reset();
            return;
        }
        if (plane > 0)
        {
            reachedRoof = true;
        }
    }

    /**
     * Return true only for an XP reward that was rejected by normal tracker
     * progression because obstacle 2 was already inferred from position.
     * Consume the claim once regardless of outcome; subsequent XP cannot
     * repeat a HUD completion. Caller applies *only* the movement-HUD callback.
     */
    boolean consumeHudOnlyXp(int gain, boolean inRegion, int stage, int plane,
        ArdougneCourseTracker.Event trackerEvent, long nowNanos)
    {
        if (!armed) { return false; }
        boolean eligible = !expired(nowNanos) &&
            gain == FIRST_OBSTACLE_XP &&
            inRegion && plane == 3 &&
            reachedRoof &&
            stage == 1 &&
            trackerEvent == ArdougneCourseTracker.Event.NONE;
        reset();
        return eligible;
    }

    void onCourseEvent(ArdougneCourseTracker.Event event, int stage)
    {
        if (event == ArdougneCourseTracker.Event.NONE ||
            (event == ArdougneCourseTracker.Event.RECOVERED && stage == 1))
        {
            return;
        }
        reset();
    }

    private boolean expired(long nowNanos)
    {
        return nowNanos < clickedAtNanos ||
            nowNanos - clickedAtNanos > MAX_CLICK_TO_XP_NANOS;
    }
}

package com.ardougnehelper;

/*
 * Camera-relative ghost clickbox approach adapted from burkeg/rooftop-obstacle-preview
 * Copyright (c) 2026, burkeg — BSD 2-Clause. See THIRD_PARTY_NOTICES.md.
 */
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.util.Arrays;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.DecorativeObject;
import net.runelite.api.GameObject;
import net.runelite.api.GroundObject;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.api.TileObject;
import net.runelite.api.WallObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Projects the FOLLOWING obstacle's hull as seen after landing on the currently highlighted one. */
public class ArdougneGhostOverlay extends Overlay
{
    // Verified Ardougne course landing tiles from burkeg's rooftop-obstacle-preview Course.java.
    // Stage 1 uses the previous lap's final ground landing tile.
    private static final WorldPoint[] LANDINGS = {
        new WorldPoint(2671, 3299, 3), new WorldPoint(2665, 3318, 3),
        new WorldPoint(2656, 3318, 3), new WorldPoint(2653, 3314, 3),
        new WorldPoint(2651, 3309, 3), new WorldPoint(2656, 3297, 3),
        new WorldPoint(2668, 3297, 0)
    };
    private static final int STEADY_FRAMES = 15;
    private static final int MAX_OFF_AXIS = 16;

    private final Client client;
    private final ArdougnePlugin plugin;
    private final ArdougneConfig config;
    private double distanceRatio = 1.25;
    private double followPerScale = 0.082;
    private final double[] previousCamera = new double[3];
    private int steadyFrames;
    private boolean calibratedThisRest;

    @Inject public ArdougneGhostOverlay(Client client, ArdougnePlugin plugin, ArdougneConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override public Dimension render(Graphics2D graphics)
    {
        if (plugin.isMarkPrioritySuppressingHulls())
        {
            return null;
        }
        Shape preview = calculatePreviewShape();
        ArdougneHullVisibility display = ArdougneHullVisibility.select(preview != null);

        // Always show exactly one obstacle hull: orange after a confirmed
        // interaction and movement, otherwise cyan as the safe fallback.
        if (display.showsCurrent())
        {
            ArdougneOverlay.drawNextObstacle(graphics, plugin, config);
        }
        if (preview != null && display.showsPreview())
        {
            Color base = config.ghostColor();
            graphics.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), config.ghostFillAlpha()));
            graphics.fill(preview);
            graphics.setColor(base);
            graphics.setStroke(new BasicStroke(2.0f)); // Solid preview border
            graphics.draw(preview);
        }
        return null;
    }

    private Shape calculatePreviewShape()
    {
        if (!plugin.isGhostPreviewActive() || !plugin.isInArdougne()) { return null; }
        Player player = client.getLocalPlayer();
        int currentStage = plugin.selectedStage();
        int futureStage = ArdougnePreviewPlan.followingStage(currentStage);
        if (player == null || futureStage < 0) { return null; }
        TileObject futureObject = plugin.objectForStage(futureStage, false);
        if (futureObject == null) { return null; }

        double pitch = client.getCameraFpPitch();
        double yaw = client.getCameraFpYaw();
        double[] forward = {-Math.sin(yaw) * Math.cos(pitch), Math.cos(yaw) * Math.cos(pitch), Math.sin(pitch)};
        double[] camera = {client.getCameraFpX(), client.getCameraFpY(), client.getCameraFpZ()};
        double formulaDistance = 600 + 3 * pitch / Perspective.UNIT;
        boolean resting = cameraAtRest(camera);
        if (resting && !calibratedThisRest)
        {
            measureCamera(camera, forward, formulaDistance, player.getLocalLocation());
        }
        calibratedThisRest = resting;
        double distance = distanceRatio * formulaDistance;
        double[] focus = new double[3];
        Arrays.setAll(focus, axis -> camera[axis] + distance * forward[axis]);

        // Project N+1 as seen from N's landing position.
        int[] offset = shift(LANDINGS[currentStage], focus);
        return offset == null ? null : clickbox(futureObject, offset[0], offset[1], offset[2]);
    }

    private int[] shift(WorldPoint tile, double[] focus)
    {
        if (client.getTopLevelWorldView() == null) { return null; }
        LocalPoint local = LocalPoint.fromWorld(client.getTopLevelWorldView(), tile.getX(), tile.getY());
        if (local == null) { return null; }
        double height = Perspective.getTileHeight(client, local, tile.getPlane()) - followPerScale * client.getScale();
        return new int[]{(int)Math.round(focus[0] - local.getX()),
            (int)Math.round(focus[1] - local.getY()), (int)Math.round(focus[2] - height)};
    }

    private Shape clickbox(TileObject object, int dx, int dy, int dz)
    {
        int x = object.getX() + dx, y = object.getY() + dy, z = object.getZ() + dz;
        if (object instanceof GameObject)
        {
            GameObject o = (GameObject) object;
            return projected(o, o.getRenderable(), o.getModelOrientation(), x, y, z);
        }
        if (object instanceof WallObject)
        {
            WallObject o = (WallObject) object;
            return combine(projected(o, o.getRenderable1(), 0, x, y, z),
                projected(o, o.getRenderable2(), 0, x, y, z));
        }
        if (object instanceof DecorativeObject)
        {
            DecorativeObject o = (DecorativeObject) object;
            return combine(projected(o, o.getRenderable(), 0, x + o.getXOffset(), y + o.getYOffset(), z),
                projected(o, o.getRenderable2(), 0, x, y, z));
        }
        if (object instanceof GroundObject)
        {
            GroundObject o = (GroundObject) object;
            return projected(o, o.getRenderable(), 0, x, y, z);
        }
        return null;
    }

    private static Shape combine(Shape a, Shape b)
    {
        if (a == null) { return b; }
        if (b == null) { return a; }
        java.awt.geom.Area merged = new java.awt.geom.Area(a);
        merged.add(new java.awt.geom.Area(b));
        return merged;
    }

    private Shape projected(TileObject object, Renderable renderable, int orientation, int x, int y, int z)
    {
        if (renderable == null) { return null; }
        Model model = renderable instanceof Model ? (Model) renderable : renderable.getModel();
        if (model == null) { return null; }
        return Perspective.getClickbox(client, object.getWorldView(), model, orientation, x, y, z);
    }

    private boolean cameraAtRest(double[] camera)
    {
        boolean moved = false;
        for (int i = 0; i < 3; i++) { moved |= Math.abs(camera[i] - previousCamera[i]) > 0.01; }
        System.arraycopy(camera, 0, previousCamera, 0, 3);
        steadyFrames = moved ? 0 : steadyFrames + 1;
        return steadyFrames >= STEADY_FRAMES;
    }

    private void measureCamera(double[] camera, double[] forward, double formulaDistance, LocalPoint at)
    {
        if (at == null || client.getTopLevelWorldView() == null) { return; }
        int ground = Perspective.getTileHeight(client, at, client.getTopLevelWorldView().getPlane());
        double denominator = forward[0] * forward[0] + forward[1] * forward[1];
        if (denominator < 0.00001) { return; }
        double along = ((at.getX() - camera[0]) * forward[0] + (at.getY() - camera[1]) * forward[1]) / denominator;
        double offAxis = Math.hypot(camera[0] + along * forward[0] - at.getX(),
            camera[1] + along * forward[1] - at.getY());
        double ratio = along / formulaDistance;
        double perScale = (ground - (camera[2] + along * forward[2])) / client.getScale();
        if (offAxis <= MAX_OFF_AXIS && ratio > 0.5 && ratio < 3 && perScale > 0.02 && perScale < 0.3)
        {
            distanceRatio = ratio;
            followPerScale += 0.3 * (perScale - followPerScale);
        }
    }
}

package com.ardougnehelper;

/** Always draws one obstacle hull: projected when available, otherwise live. */
enum ArdougneHullVisibility
{
    CURRENT_ONLY, PREVIEW_ONLY;

    static ArdougneHullVisibility select(boolean projectionAvailable)
    {
        return projectionAvailable ? PREVIEW_ONLY : CURRENT_ONLY;
    }

    boolean showsCurrent() { return this == CURRENT_ONLY; }
    boolean showsPreview() { return this == PREVIEW_ONLY; }
}

package com.ardougnehelper;

/**
 * An optional visual-only collection window at Ardougne obstacle 4.
 *
 * A valid obstacle-3 interaction plus confirmed departure permits priority
 * mode ONLY when the Mark threshold is actually met. With no qualifying Marks,
 * the ordinary preview remains available during obstacle-3 traversal.
 * Obstacle-3 XP authorizes collecting Marks at obstacle 4, including ones that
 * appear late. Traversal XP is independent of a mere click/animation.
 *
 * After priority begins, mark highlighting stays latched until TWO valid,
 * consecutive scene scans find zero current-plane marks. This prevents a
 * threshold of two from hiding the final remaining Mark.
 *
 * This class neither generates input nor communicates outside the client.
 */
final class ArdougneMarkPriority
{
    static final int THIRD_OBSTACLE = 2; // Zero-based index.
    static final int FOURTH_OBSTACLE = 3;
    static final int CLICK_CONFIRM_TIMEOUT_TICKS = 10;
    static final int TRAVERSAL_TIMEOUT_TICKS = 20;
    static final int EMPTY_CONFIRM_TICKS = 2;

    enum Mode { NORMAL, WAITING_FOR_LANDING, COLLECTING }

    private volatile Mode mode = Mode.NORMAL;
    private boolean thirdClickPending;
    private int thirdClickTick;
    private int waitStartTick;
    private boolean fourthObstacleWindow;
    private int emptyTicks;

    void reset()
    {
        mode = Mode.NORMAL;
        thirdClickPending = false;
        fourthObstacleWindow = false;
        emptyTicks = 0;
    }

    /** Called after the menu action has passed the plugin's object-ID checks. */
    void onValidObstacleClick(int clickedStage, int tick)
    {
        if (clickedStage == THIRD_OBSTACLE)
        {
            thirdClickPending = true;
            thirdClickTick = tick;
            fourthObstacleWindow = false;
            emptyTicks = 0;
        }
        else if (clickedStage == FOURTH_OBSTACLE)
        {
            // The user chose to continue the course; the collection window
            // must not reopen just because a late mark appears during obstacle 4.
            reset();
        }
    }

    /** Completion XP is sufficient even when movement was missed between ticks. */
    void onThirdObstacleCompleted()
    {
        if (thirdClickPending || mode == Mode.WAITING_FOR_LANDING)
        {
            thirdClickPending = false;
            // A no-Mark transition remains NORMAL so preview 4 is not hidden.
            // The collection window still opens for a late Mark at stage 4.
            fourthObstacleWindow = true;
            emptyTicks = 0;
        }
    }

    /**
     * Returns true if a stalled obstacle-3 traversal exceeded its bounded wait.
     * The caller can then reset its preview gate to restore a clickable cyan
     * obstacle rather than leaving an indefinitely blank screen.
     */
    boolean onTick(boolean enabled, boolean onRooftop, int selectedStage,
        boolean thirdMovementConfirmed, int markCount, int threshold,
        boolean validMarkScan, int tick)
    {
        if (!enabled || !onRooftop)
        {
            reset();
            return false;
        }

        if (selectedStage == THIRD_OBSTACLE)
        {
            if (thirdClickPending && tick - thirdClickTick > CLICK_CONFIRM_TIMEOUT_TICKS)
            {
                thirdClickPending = false;
            }
            if (thirdClickPending && thirdMovementConfirmed && validMarkScan &&
                markCount >= Math.max(1, threshold) && mode != Mode.WAITING_FOR_LANDING)
            {
                mode = Mode.WAITING_FOR_LANDING;
                waitStartTick = tick;
                // Retain thirdClickPending until completion so a verified
                // obstacle-3 XP event can open the stage-4 collection window.
                emptyTicks = 0;
            }
            if (mode == Mode.WAITING_FOR_LANDING &&
                tick - waitStartTick > TRAVERSAL_TIMEOUT_TICKS)
            {
                reset();
                return true;
            }
            return false;
        }

        if (selectedStage != FOURTH_OBSTACLE)
        {
            reset();
            return false;
        }

        // The expected stage advanced. A verified previous movement or third
        // obstacle XP is required; stage recovery alone is not sufficient.
        if (!fourthObstacleWindow && mode == Mode.WAITING_FOR_LANDING)
        {
            fourthObstacleWindow = true;
            emptyTicks = 0;
        }
        if (!fourthObstacleWindow || !validMarkScan)
        {
            return false;
        }

        if (mode == Mode.COLLECTING)
        {
            if (markCount > 0)
            {
                emptyTicks = 0;
            }
            else if (++emptyTicks >= EMPTY_CONFIRM_TICKS)
            {
                mode = Mode.NORMAL;
                emptyTicks = 0;
            }
        }
        else if (markCount >= Math.max(1, threshold))
        {
            mode = Mode.COLLECTING;
            emptyTicks = 0;
        }
        else if (mode == Mode.WAITING_FOR_LANDING && ++emptyTicks >= EMPTY_CONFIRM_TICKS)
        {
            // No threshold-qualified mark appeared at the landing. Resume
            // normal overlays, but allow later marks before obstacle 4 is clicked.
            mode = Mode.NORMAL;
            emptyTicks = 0;
        }
        return false;
    }

    boolean suppressObstacleHulls() { return mode != Mode.NORMAL; }
    boolean showExclusiveMarks() { return mode == Mode.COLLECTING; }
    Mode mode() { return mode; }
}

package com.ardougnehelper;

/**
 * Visual HUD activity evidence from high-frequency client ticks. Real local/
 * world position changes, walking poses, and action animations all mean
 * ACTIVE (yellow). Before the stage completes, a longer rooftop hold covers
 * short animation gaps. XP-confirmed stage advancement ends that long hold.
 * On obstacles 1, 3 and 6, a brief post-XP settling window ignores the old
 * actor animation if the character's position is stable. Obstacle 1 additionally
 * guards against a quiet frame at XP followed by delayed residual animations
 * after the ground-to-roof transition. The other six obstacles keep their
 * existing completion behavior.
 *
 * Movement state is a HUD signal, NOT traversal completion or permission to click.
 */
final class ArdougneMotionTracker
{
    static final long GROUND_HOLD_NANOS = 350_000_000L;
    static final long ROOFTOP_HOLD_NANOS = 1_300_000_000L;
    // Short post-completion gap coverage, rather than the normal 1.3-second
    // rooftop hold. This permits the HUD to settle almost immediately after XP.
    static final long POST_XP_HOLD_NANOS = 100_000_000L;
    // A split wall-climb animation can briefly be idle when obstacle 1 XP
    // arrives, then resume reporting actor animation on the roof. This window
    // suppresses only residual ACTOR animation evidence, not actual movement.
    // It begins at the first verified rooftop observation if XP arrived on ground.
    static final long FIRST_OBSTACLE_RESIDUAL_GUARD_NANOS = 1_600_000_000L;
    // An XP event cannot leave the HUD permanently yellow if a first-obstacle
    // roof plane never materializes (fall/interruption, stale scene, etc.).
    static final long FIRST_ROOF_WAIT_NANOS = 6_000_000_000L;

    private boolean sampled;
    private int localX, localY, worldX, worldY, plane;
    private long lastMotion;
    private long lastMotionHoldNanos;
    private boolean hasMotionEvidence;
    private boolean xpFinishing;
    // Obstacle 1, 3 and 6 may continue reporting a residual animation after
    // their reward has arrived; ignore it until both action and walking pose
    // return to idle. Do NOT suppress actual position changes or new in-flight
    // activity. Other obstacles keep the v0.2.7 rules unchanged.
    private boolean suppressResidualAnimation;
    // Obstacle 1 is the only fast-settle transition that climbs from ground.
    // If XP precedes its plane change, do not call it ground-stationary.
    private boolean awaitRoofAfterFirstXp;
    private long firstXpAtNanos;
    private boolean firstObstacleResidualGuard;
    private long firstObstacleGuardUntilNanos;
    private volatile boolean moving;

    void reset()
    {
        sampled = false;
        hasMotionEvidence = false;
        xpFinishing = false;
        suppressResidualAnimation = false;
        awaitRoofAfterFirstXp = false;
        firstXpAtNanos = 0;
        firstObstacleResidualGuard = false;
        firstObstacleGuardUntilNanos = 0;
        moving = false;
    }

    void observe(boolean valid, int lx, int ly, int wx, int wy, int p,
        int poseAnimation, int idlePoseAnimation, int actionAnimation, long nowNanos)
    {
        observe(valid, lx, ly, wx, wy, p, poseAnimation, idlePoseAnimation,
            actionAnimation, nowNanos, false);
    }

    /** In-flight means the plugin observed departure after a valid obstacle click. */
    void observe(boolean valid, int lx, int ly, int wx, int wy, int p,
        int poseAnimation, int idlePoseAnimation, int actionAnimation, long nowNanos,
        boolean inFlight)
    {
        if (!valid)
        {
            reset();
            return;
        }

        boolean positionChanged = positionChanged(lx, ly, wx, wy, p);
        boolean walkingPose = isWalking(poseAnimation, idlePoseAnimation);
        boolean activeAnimation = actionAnimation >= 0;
        if (awaitRoofAfterFirstXp)
        {
            long roofWait = nowNanos - firstXpAtNanos;
            if (roofWait >= FIRST_ROOF_WAIT_NANOS)
            {
                // Bounded fail-safe: allow the HUD to report the *actual*
                // ground plane again; never invent arrival at a roof.
                awaitRoofAfterFirstXp = false;
                firstObstacleResidualGuard = false;
                suppressResidualAnimation = false;
                xpFinishing = false;
                hasMotionEvidence = false;
            }
            else if (p > 0)
            {
                // XP was accepted on plane 0; wait for the *real* roof plane
                // before considering fast stationary. The plane change itself
                // remains genuine movement on this observation.
                awaitRoofAfterFirstXp = false;
                // Start the finite residual-animation guard only after an
                // actual rooftop plane appears, never on ground-level XP.
                firstObstacleGuardUntilNanos = nowNanos +
                    FIRST_OBSTACLE_RESIDUAL_GUARD_NANOS;
                suppressResidualAnimation = false;
                xpFinishing = true;
            }
        }
        if (firstObstacleResidualGuard)
        {
            if (inFlight)
            {
                // A new valid obstacle click with confirmed departure belongs
                // to the NEXT traversal. Restore full motion detection and its
                // original 1.3-second gap hold for this independent action.
                firstObstacleResidualGuard = false;
                xpFinishing = false;
                hasMotionEvidence = false;
            }
            else if (!awaitRoofAfterFirstXp &&
                nowNanos >= firstObstacleGuardUntilNanos)
            {
                // Do not permanently hide independent player animations.
                firstObstacleResidualGuard = false;
            }
            else
            {
                // A split first-wall animation may restart AFTER a completely
                // idle XP frame. Do not let it re-arm a long yellow hold.
                // Genuine local/world/plane movement is still checked below.
                walkingPose = false;
                activeAnimation = false;
            }
        }
        if (suppressResidualAnimation)
        {
            if (!walkingPose && !activeAnimation)
            {
                // Once the old traversal is fully idle, subsequent new
                // animations are independent and must show yellow as usual.
                suppressResidualAnimation = false;
            }
            else
            {
                walkingPose = false;
                activeAnimation = false;
            }
        }
        boolean motionEvidence = positionChanged || walkingPose || activeAnimation ||
            inFlight || awaitRoofAfterFirstXp;

        if (motionEvidence)
        {
            lastMotion = nowNanos;
            hasMotionEvidence = true;
            // XP has already confirmed the preceding stage: don't keep the
            // 1.3-second hold alive because the actor is finishing its animation.
            lastMotionHoldNanos = (xpFinishing || suppressResidualAnimation ||
                awaitRoofAfterFirstXp || firstObstacleResidualGuard) ? POST_XP_HOLD_NANOS :
                (p > 0 || (sampled && plane > 0) ? ROOFTOP_HOLD_NANOS : GROUND_HOLD_NANOS);
        }
        long elapsed = nowNanos - lastMotion;
        moving = motionEvidence || (hasMotionEvidence && elapsed >= 0 &&
            elapsed < lastMotionHoldNanos);

        storePosition(lx, ly, wx, wy, p);
        if (xpFinishing && !moving)
        {
            // The first confirmed post-XP rest ends the short-hold phase.
            // Later, new movement gets the normal gap protection again.
            xpFinishing = false;
            hasMotionEvidence = false;
        }
    }

    /**
     * Called ONLY after the course tracker accepts a matching obstacle-XP
     * stage advancement or completed-lap award (not on arbitrary Agility XP).
     *
     * Clear the historical 1.3-second hold and sample live actor state. With
     * the legacy (non-fast) policy, continue yellow while animations remain.
     * For fast stages 1, 3 and 6, ignore a residual pre-XP animation after a
     * short settling interval with no real movement. Obstacle 1's split wall
     * animation can also go temporarily idle at XP and resume later, so it
     * needs a bounded guard that survives an idle sample. The actual plane
     * always determines which stationary HUD color is permissible.
     */
    void onConfirmedCourseXp(boolean valid, int lx, int ly, int wx, int wy, int p,
        int poseAnimation, int idlePoseAnimation, int actionAnimation, long nowNanos)
    {
        onConfirmedCourseXp(valid, lx, ly, wx, wy, p,
            poseAnimation, idlePoseAnimation, actionAnimation, nowNanos, -1);
    }

    /**
     * completedObstacle is zero-based. Obstacles 1, 3 and 6 have an XP-gated
     * position-settling exception for residual animation IDs (not an exception
     * to actual movement evidence). Other stages retain the old behavior.
     */
    void onConfirmedCourseXp(boolean valid, int lx, int ly, int wx, int wy, int p,
        int poseAnimation, int idlePoseAnimation, int actionAnimation, long nowNanos,
        int completedObstacle)
    {
        if (!valid)
        {
            return;
        }
        boolean positionChanged = positionChanged(lx, ly, wx, wy, p);
        boolean walkingPose = isWalking(poseAnimation, idlePoseAnimation);
        boolean activeAnimation = actionAnimation >= 0;
        storePosition(lx, ly, wx, wy, p);
        lastMotion = nowNanos;
        lastMotionHoldNanos = POST_XP_HOLD_NANOS;

        boolean fastSettle = completedObstacle == 0 || completedObstacle == 2 ||
            completedObstacle == 5;
        firstObstacleResidualGuard = completedObstacle == 0;
        firstObstacleGuardUntilNanos = (firstObstacleResidualGuard && p > 0) ?
            nowNanos + FIRST_OBSTACLE_RESIDUAL_GUARD_NANOS : 0;
        if (fastSettle)
        {
            // A new stage is credited, but RuneLite may keep reporting the
            // preceding obstacle's actor animation after the character has
            // physically stopped. On these three transitions, stop treating
            // that stale animation alone as evidence of travel.
            awaitRoofAfterFirstXp = completedObstacle == 0 && p == 0;
            firstXpAtNanos = nowNanos;
            suppressResidualAnimation = !firstObstacleResidualGuard &&
                (walkingPose || activeAnimation);
            xpFinishing = true;
            // One short (100 ms) post-XP interval also covers an animation
            // still active exactly at the reward event. This avoids flashing
            // stationary on that same frame, but skips its long lingering tail.
            hasMotionEvidence = positionChanged || awaitRoofAfterFirstXp ||
                walkingPose || activeAnimation;
            moving = hasMotionEvidence;
            return;
        }

        awaitRoofAfterFirstXp = false;
        suppressResidualAnimation = false;
        boolean liveActivity = positionChanged || walkingPose || activeAnimation;
        xpFinishing = liveActivity;
        hasMotionEvidence = liveActivity;
        moving = liveActivity;
    }

    private boolean positionChanged(int lx, int ly, int wx, int wy, int p)
    {
        return sampled && (lx != localX || ly != localY ||
            wx != worldX || wy != worldY || p != plane);
    }

    private static boolean isWalking(int pose, int idle)
    {
        return pose >= 0 && idle >= 0 && pose != idle;
    }

    private void storePosition(int lx, int ly, int wx, int wy, int p)
    {
        localX = lx;
        localY = ly;
        worldX = wx;
        worldY = wy;
        plane = p;
        sampled = true;
    }

    boolean isMoving() { return moving; }
}

package com.ardougnehelper;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Shape;
import javax.inject.Inject;
import net.runelite.api.ItemLayer;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class ArdougneOverlay extends Overlay
{
    private final ArdougnePlugin plugin;
    private final ArdougneConfig config;

    @Inject public ArdougneOverlay(ArdougnePlugin plugin, ArdougneConfig config)
    {
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override public Dimension render(Graphics2D graphics)
    {
        // The ghost overlay owns the sole obstacle hull (current or preview).
        // With Mark Priority off, ground Marks remain independent of that choice.
        drawGroundMarks(graphics);
        return null;
    }

    /** The ghost overlay draws this whenever the projected hull is unavailable. */
    static void drawNextObstacle(Graphics2D graphics, ArdougnePlugin plugin, ArdougneConfig config)
    {
        TileObject object = plugin.selectedObject();
        if (object == null) { return; }
        Shape hull = object.getClickbox();
        if (hull == null) { return; }
        Color color = config.hullColor();
        graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), config.fillAlpha()));
        graphics.fill(hull);
        graphics.setStroke(new BasicStroke(2.0f));
        graphics.setColor(color);
        graphics.draw(hull);
    }

    private void drawGroundMarks(Graphics2D graphics)
    {
        if (!config.highlightMarks() || !plugin.isInArdougne() ||
            (config.prioritizeMarks() ? !plugin.isExclusiveMarkMode() :
                !ArdougnePlugin.shouldHighlightMarks(plugin.groundMarkCount(), config.minimumGroundMarks())))
        {
            return;
        }

        Color color = config.markColor();
        graphics.setStroke(new BasicStroke(2.0f));
        for (Tile tile : plugin.groundMarkTiles())
        {
            ItemLayer itemLayer = tile.getItemLayer();
            if (itemLayer == null) { continue; }
            Polygon tilePoly = itemLayer.getCanvasTilePoly();
            if (tilePoly == null) { continue; }
            graphics.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), config.fillAlpha()));
            graphics.fill(tilePoly);
            graphics.setColor(color);
            graphics.draw(tilePoly);
        }
    }
}

package com.ardougnehelper;

import com.google.inject.Provides;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.inject.Inject;
import net.runelite.api.*;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.events.*;
import net.runelite.api.gameval.ObjectID;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(name = "Simple Ardougne Rooftop", description = "One highlighted Ardougne rooftop obstacle at a time, with optional Mark of Grace highlighting", tags = {"agility", "ardougne", "rooftop", "marks"})
public class ArdougnePlugin extends Plugin
{
    // Identifiers sourced from RuneLite's official Agility Obstacles list.
    static final int[] IDS = {
        ObjectID.ROOFTOPS_ARDY_WALLCLIMB,
        ObjectID.ROOFTOPS_ARDY_JUMP,
        ObjectID.ROOFTOPS_ARDY_PLANK,
        ObjectID.ROOFTOPS_ARDY_JUMP_2,
        ObjectID.ROOFTOPS_ARDY_JUMP_3,
        ObjectID.ROOFTOPS_ARDY_WALLCROSSING,
        ObjectID.ROOFTOPS_ARDY_JUMP_4
    };
    static final String[] LABELS = {"Wooden beams", "Gap 1", "Plank", "Gap 2", "Gap 3", "Steep roof", "Final gap"};
    static final int REGION = 10547;

    @Inject private Client client;
    @Inject private ArdougneConfig config;
    @Inject private OverlayManager overlayManager;
    @Inject private ArdougneOverlay overlay;
    @Inject private ArdougneStageOverlay stageOverlay;
    @Inject private ArdougneGhostOverlay ghostOverlay;

    private final Map<TileObject, Integer> objects = new ConcurrentHashMap<>();
    private int lastObstacleScanTick = -1000;
    private final ArdougneCourseTracker tracker = new ArdougneCourseTracker();
    private final ArdougnePreviewGate previewGate = new ArdougnePreviewGate();
    private final ArdougneMarkPriority markPriority = new ArdougneMarkPriority();
    private final ArdougneMotionTracker motionTracker = new ArdougneMotionTracker();
    private final ArdougneFirstObstacleHudXp firstObstacleHudXp = new ArdougneFirstObstacleHudXp();
    private int lastXp = -1;
    private String lastStatus;
    private int lastStatusTick = -100;

    // Snapshot lists are replaced atomically on each game tick to prevent
    // concurrent modification while the overlay renders on the client UI.
    private volatile List<Tile> groundMarkTiles = Collections.emptyList();
    private volatile int groundMarkCount = 0;
    private volatile boolean groundMarkScanValid;

    @Provides ArdougneConfig provideConfig(ConfigManager cm) { return cm.getConfig(ArdougneConfig.class); }

    @Override protected void startUp()
    {
        overlayManager.add(overlay);
        overlayManager.add(stageOverlay);
        overlayManager.add(ghostOverlay);
        objects.clear();
        lastObstacleScanTick = -1000;
        tracker.clearSession();
        previewGate.reset();
        markPriority.reset();
        motionTracker.reset();
        firstObstacleHudXp.reset();
        lastXp = -1;
        lastStatus = null;
        resetMarks();
    }

    @Override protected void shutDown()
    {
        overlayManager.remove(overlay);
        overlayManager.remove(stageOverlay);
        overlayManager.remove(ghostOverlay);
        objects.clear();
        lastObstacleScanTick = -1000;
        tracker.clearSession();
        previewGate.reset();
        markPriority.reset();
        motionTracker.reset();
        firstObstacleHudXp.reset();
        lastXp = -1;
        resetMarks();
    }

    @Subscribe public void onGameStateChanged(GameStateChanged e)
    {
        if (e.getGameState() == GameState.LOADING || e.getGameState() == GameState.LOGIN_SCREEN || e.getGameState() == GameState.HOPPING)
        {
            objects.clear();
            lastObstacleScanTick = -1000;
            resetMarks();
            previewGate.reset();
            markPriority.reset();
            motionTracker.reset();
            firstObstacleHudXp.reset();
            record(tracker.onSceneLoading());
            if (e.getGameState() != GameState.LOADING)
            {
                lastXp = -1;
            }
        }
    }

    /**
     * Only a real interaction with the cyan-selected obstacle can arm the
     * preview. Examine, walking, and ground-item clicks are excluded. The
     * event indicates an attempted interaction, NOT confirmed completion.
     */
    @Subscribe public void onMenuOptionClicked(MenuOptionClicked e)
    {
        boolean previewOrMark = config.showGhostPreview() || isMarkPriorityEnabled();
        boolean hudEnabled = config.enableHud() && config.friendlyTaunt();
        if ((!previewOrMark && !hudEnabled) || e.isConsumed() ||
            !isObstacleInteraction(e.getMenuAction()))
        {
            return;
        }
        Player player = client.getLocalPlayer();
        if (player == null) { return; }
        WorldPoint at = player.getWorldLocation();
        if (at == null || at.getRegionID() != REGION) { return; }
        int currentStage = selectedStage();
        if (currentStage < 0 || currentStage >= IDS.length || e.getId() != IDS[currentStage])
        {
            return;
        }
        // Capture the actor's pre-interaction state so a new animation can
        // corroborate departure even if world-tile movement is not sampled.
        LocalPoint local = player.getLocalLocation();
        int lx = local == null ? Integer.MIN_VALUE : local.getX();
        int ly = local == null ? Integer.MIN_VALUE : local.getY();
        if (previewOrMark)
        {
            previewGate.onValidObstacleClick(currentStage, currentStage, client.getTickCount(),
                at.getX(), at.getY(), at.getPlane(), lx, ly,
                player.getAnimation(), player.getPoseAnimation(), player.getIdlePoseAnimation());
        }
        if (hudEnabled)
        {
            firstObstacleHudXp.onValidObstacleClick(currentStage, at.getPlane(), System.nanoTime());
        }
        if (isMarkPriorityEnabled())
        {
            markPriority.onValidObstacleClick(currentStage, client.getTickCount());
        }
    }

    static boolean isObstacleInteraction(MenuAction action)
    {
        if (action == null) { return false; }
        switch (action)
        {
            case GAME_OBJECT_FIRST_OPTION:
            case GAME_OBJECT_SECOND_OPTION:
            case GAME_OBJECT_THIRD_OPTION:
            case GAME_OBJECT_FOURTH_OPTION:
            case GAME_OBJECT_FIFTH_OPTION:
                return true;
            default:
                return false;
        }
    }

    /** Changing preview or Mark settings must not reuse an old click/window. */
    @Subscribe public void onConfigChanged(ConfigChanged event)
    {
        if (!"ardougnenext".equals(event.getGroup())) { return; }
        if ("showGhostPreview".equals(event.getKey()) ||
            "prioritizeMarks".equals(event.getKey()) ||
            "highlightMarks".equals(event.getKey()))
        {
            previewGate.reset();
            markPriority.reset();
        }
        if ("enableHud".equals(event.getKey()) ||
            "friendlyTaunt".equals(event.getKey()))
        {
            firstObstacleHudXp.reset();
        }
    }

    @Subscribe public void onGameObjectSpawned(GameObjectSpawned e) { add(e.getGameObject()); }
    @Subscribe public void onGameObjectDespawned(GameObjectDespawned e) { objects.remove(e.getGameObject()); }
    @Subscribe public void onWallObjectSpawned(WallObjectSpawned e) { add(e.getWallObject()); }
    @Subscribe public void onWallObjectDespawned(WallObjectDespawned e) { objects.remove(e.getWallObject()); }
    @Subscribe public void onGroundObjectSpawned(GroundObjectSpawned e) { add(e.getGroundObject()); }
    @Subscribe public void onGroundObjectDespawned(GroundObjectDespawned e) { objects.remove(e.getGroundObject()); }
    @Subscribe public void onDecorativeObjectSpawned(DecorativeObjectSpawned e) { add(e.getDecorativeObject()); }
    @Subscribe public void onDecorativeObjectDespawned(DecorativeObjectDespawned e) { objects.remove(e.getDecorativeObject()); }

    /**
     * Spawn notifications alone do not guarantee that the entry obstacle is
     * indexed when a lap/fall returns the player to the ground. Rebuild the
     * index from the *currently loaded scene* at those transitions, and retry
     * occasionally if the highlighted object is still unavailable.
     *
     * This never changes the course stage or triggers gameplay input.
     */
    private void rescanLoadedObstacles()
    {
        Scene scene = client.getScene();
        if (scene == null || scene.getTiles() == null) { return; }

        objects.clear();
        for (Tile[][] tilesByX : scene.getTiles())
        {
            if (tilesByX == null) { continue; }
            for (Tile[] tilesByY : tilesByX)
            {
                if (tilesByY == null) { continue; }
                for (Tile tile : tilesByY)
                {
                    if (tile == null || tile.getWorldLocation() == null ||
                        tile.getWorldLocation().getRegionID() != REGION) { continue; }

                    GameObject[] gameObjects = tile.getGameObjects();
                    if (gameObjects != null)
                    {
                        for (GameObject gameObject : gameObjects) { add(gameObject); }
                    }
                    add(tile.getWallObject());
                    add(tile.getGroundObject());
                    add(tile.getDecorativeObject());
                }
            }
        }
        lastObstacleScanTick = client.getTickCount();
    }

    boolean hasTrackedStageObject(int stage)
    {
        if (stage < 0) { return false; }
        for (Map.Entry<TileObject, Integer> entry : objects.entrySet())
        {
            if (entry.getValue() == stage) { return true; }
        }
        return false;
    }

    private boolean hasVisibleStageObject(int stage)
    {
        if (stage < 0) { return false; }
        for (Map.Entry<TileObject, Integer> entry : objects.entrySet())
        {
            TileObject object = entry.getKey();
            if (entry.getValue() == stage && object.getClickbox() != null)
            {
                return true;
            }
        }
        return false;
    }

    private void add(TileObject object)
    {
        if (object == null || object.getWorldLocation() == null) { return; }
        for (int i = 0; i < IDS.length; i++)
        {
            if (object.getId() == IDS[i] && object.getWorldLocation().getRegionID() == REGION)
            {
                objects.put(object, i);
                return;
            }
        }
    }

    /**
     * Observe actor position/animation every client tick. The preview gate
     * needs this independently of HUD settings: otherwise short obstacle
     * traversals can finish before the next 600 ms game-tick observation.
     */
    @Subscribe public void onClientTick(ClientTick tick)
    {
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            firstObstacleHudXp.reset();
            motionTracker.reset();
            return;
        }
        Player player = client.getLocalPlayer();
        if (player == null)
        {
            firstObstacleHudXp.reset();
            motionTracker.reset();
            return;
        }
        WorldPoint world = player.getWorldLocation();
        LocalPoint local = player.getLocalLocation();
        if (world == null || local == null || world.getRegionID() != REGION ||
            world.getPlane() < 0 || world.getPlane() > 3)
        {
            firstObstacleHudXp.reset();
            motionTracker.reset();
            return;
        }

        firstObstacleHudXp.observe(true, selectedStage(), world.getPlane(), System.nanoTime());
        int action = player.getAnimation();
        int pose = player.getPoseAnimation();
        int idlePose = player.getIdlePoseAnimation();
        if ((config.showGhostPreview() || isMarkPriorityEnabled()) &&
            previewGate.isPendingFor(selectedStage()))
        {
            previewGate.onClientActivity(selectedStage(), client.getTickCount(),
                world.getX(), world.getY(), world.getPlane(), local.getX(), local.getY(),
                action, pose, idlePose);
        }
        if (config.enableHud() && config.friendlyTaunt())
        {
            motionTracker.observe(true, local.getX(), local.getY(),
                world.getX(), world.getY(), world.getPlane(), pose, idlePose,
                action, System.nanoTime(),
                previewGate.isInFlightFor(selectedStage(), client.getTickCount()));
        }
        else
        {
            motionTracker.reset();
        }
    }

    @Subscribe public void onGameTick(GameTick tick)
    {
        Player player = client.getLocalPlayer();
        if (player == null) { return; }

        if (lastXp < 0)
        {
            lastXp = client.getSkillExperience(Skill.AGILITY);
        }

        WorldPoint at = player.getWorldLocation();
        if (at == null) { return; }
        boolean inside = at.getRegionID() == REGION;
        if (!inside)
        {
            resetMarks();
        }
        else
        {
            refreshGroundMarks(at.getPlane());
        }
        ArdougneCourseTracker.Event result = tracker.onPosition(inside, at.getX(), at.getY(), at.getPlane(), inside ? inferStage(at) : -1);
        firstObstacleHudXp.observe(inside, selectedStage(), at.getPlane(), System.nanoTime());
        firstObstacleHudXp.onCourseEvent(result, selectedStage());
        // Clear the click-confirmation gate whenever the underlying course
        // tracker changes stage or declares a lap/fall/interruption.
        if (result != ArdougneCourseTracker.Event.NONE)
        {
            previewGate.reset();
        }
        if (inside)
        {
            previewGate.onTick(selectedStage(), client.getTickCount(),
                at.getX(), at.getY(), at.getPlane());
        }
        else
        {
            previewGate.reset();
        }
        boolean timedOut = markPriority.onTick(isMarkPriorityEnabled(),
            inside && at.getPlane() >= 1 && at.getPlane() <= 3,
            selectedStage(), previewGate.isActiveFor(ArdougneMarkPriority.THIRD_OBSTACLE),
            groundMarkCount, config.minimumGroundMarks(), groundMarkScanValid,
            client.getTickCount());
        if (timedOut)
        {
            // A movement-confirmed click without traversal XP cannot suppress
            // both hulls indefinitely. Restore the normal live cyan fallback.
            previewGate.reset();
        }
        record(result);
        if (inside)
        {
            // The scene may already have been rebuilt, with the initial beams
            // missing from our spawn-event cache. Re-index when returning to
            // stage 1, and keep retrying at a low frequency if still missing.
            int targetStage = selectedStage();
            boolean reset = result == ArdougneCourseTracker.Event.FALL ||
                result == ArdougneCourseTracker.Event.UNVERIFIED_FINISH;
            // Previews also need the NEXT obstacle in the scene cache.
            // It might not be directly clickable yet, so only require that
            // its object exists, not that getClickbox() is non-null.
            int futureStage = config.showGhostPreview() ? ArdougnePreviewPlan.followingStage(targetStage) : -1;
            boolean missingCurrent = targetStage >= 0 && !hasVisibleStageObject(targetStage);
            boolean missingFuture = futureStage >= 0 && !hasTrackedStageObject(futureStage);
            if (reset || ((missingCurrent || missingFuture) &&
                client.getTickCount() - lastObstacleScanTick >= 3))
            {
                rescanLoadedObstacles();
            }
        }
    }

    @Subscribe public void onStatChanged(StatChanged e)
    {
        if (e.getSkill() != Skill.AGILITY) { return; }
        int xp = e.getXp();
        if (lastXp < 0) { lastXp = xp; return; }
        int gain = xp - lastXp;
        lastXp = xp;
        Player player = client.getLocalPlayer();
        if (player == null || player.getWorldLocation() == null) { return; }
        WorldPoint location = player.getWorldLocation();
        int beforeStage = selectedStage();
        ArdougneCourseTracker.Event result = tracker.onExperienceGain(gain, location.getRegionID() == REGION, location.getPlane());
        // A 43 XP callback may be the first sample taken on plane 3. Observe
        // that real roof plane before evaluating the single-use HUD-only claim.
        firstObstacleHudXp.observe(location.getRegionID() == REGION,
            selectedStage(), location.getPlane(), System.nanoTime());
        // Position recovery can already show stage 1 before the 43 XP arrives.
        // The course tracker rejects that older reward. Recognize it for HUD
        // settling only, without changing stage, preview, or Mark logic.
        boolean firstObstacleHudOnly = firstObstacleHudXp.consumeHudOnlyXp(gain,
            location.getRegionID() == REGION, selectedStage(), location.getPlane(),
            result, System.nanoTime());
        if (beforeStage == ArdougneMarkPriority.THIRD_OBSTACLE &&
            selectedStage() == ArdougneMarkPriority.FOURTH_OBSTACLE &&
            result == ArdougneCourseTracker.Event.ADVANCED && isMarkPriorityEnabled())
        {
            // XP confirms obstacle 3 completion even if the movement interval
            // was too brief to be sampled by the preview gate.
            markPriority.onThirdObstacleCompleted();
        }
        if (result != ArdougneCourseTracker.Event.NONE)
        {
            previewGate.reset();
        }
        if ((result == ArdougneCourseTracker.Event.ADVANCED ||
            result == ArdougneCourseTracker.Event.LAP || firstObstacleHudOnly) &&
            config.enableHud() && config.friendlyTaunt())
        {
            // Accepted course XP, or the bounded obstacle-1 HUD-only fallback,
            // may end the prior long yellow hold. Neither bypasses live movement.
            LocalPoint local = player.getLocalLocation();
            if (local != null)
            {
                motionTracker.onConfirmedCourseXp(true, local.getX(), local.getY(),
                    location.getX(), location.getY(), location.getPlane(),
                    player.getPoseAnimation(), player.getIdlePoseAnimation(),
                    player.getAnimation(), System.nanoTime(),
                    result == ArdougneCourseTracker.Event.LAP ?
                        ArdougneCourseTracker.STAGE_COUNT - 1 :
                        firstObstacleHudOnly ? 0 : selectedStage() - 1);
            }
        }
        record(result);
        if (result == ArdougneCourseTracker.Event.LAP)
        {
            // A completed lap returns to ground-level Wooden Beams. Refresh
            // the scene index immediately, even if no spawn event was posted.
            rescanLoadedObstacles();
        }
    }

    /** Infer the next obstacle from the nearest obstacle on the player's roof. */
    private int inferStage(WorldPoint at)
    {
        int bestStage = -1;
        int bestDistance = Integer.MAX_VALUE;
        for (Map.Entry<TileObject, Integer> entry : objects.entrySet())
        {
            WorldPoint wp = entry.getKey().getWorldLocation();
            if (wp == null || wp.getPlane() != at.getPlane()) { continue; }
            int distance = wp.distanceTo2D(at);
            if (distance < bestDistance)
            {
                bestDistance = distance;
                bestStage = entry.getValue();
            }
        }
        // Do not guess from distant scenery on the same floor.
        return bestDistance <= 20 ? bestStage : -1;
    }

    private void record(ArdougneCourseTracker.Event event)
    {
        if (event == ArdougneCourseTracker.Event.NONE || event == ArdougneCourseTracker.Event.ADVANCED)
        {
            return;
        }
        switch (event)
        {
            case FALL: lastStatus = "Fall detected - reset to beams"; break;
            case LAP: lastStatus = "Lap completed"; break;
            case RECOVERED: lastStatus = "Stage recovered from position"; break;
            case INTERRUPTED: lastStatus = "Course interrupted - no fall counted"; break;
            case UNVERIFIED_FINISH: lastStatus = "Finish unverified - no fall counted"; break;
            default: return;
        }
        lastStatusTick = client.getTickCount();
    }

    String recentStatus()
    {
        return lastStatus != null && client.getTickCount() - lastStatusTick <= 12 ? lastStatus : null;
    }

    int lapCount() { return tracker.getLaps(); }
    int fallCount() { return tracker.getFalls(); }

    /** Count item quantities, not just tiles, so stacks count correctly. */
    private void refreshGroundMarks(int plane)
    {
        Scene scene = client.getScene();
        if (scene == null)
        {
            resetMarks();
            return;
        }
        Tile[][][] tiles = scene.getTiles();
        if (tiles == null || plane < 0 || plane >= tiles.length || tiles[plane] == null)
        {
            resetMarks();
            return;
        }

        List<Tile> foundTiles = new ArrayList<>();
        int foundCount = 0;
        boolean scannedCourseTile = false;
        for (Tile[] column : tiles[plane])
        {
            if (column == null) { continue; }
            for (Tile tile : column)
            {
                if (tile == null || tile.getWorldLocation() == null ||
                    tile.getWorldLocation().getRegionID() != REGION) { continue; }
                scannedCourseTile = true;
                List<TileItem> items = tile.getGroundItems();
                if (items == null) { continue; }
                boolean hasMark = false;
                for (TileItem item : items)
                {
                    if (item != null && item.getId() == ItemID.GRACE)
                    {
                        foundCount += Math.max(1, item.getQuantity());
                        hasMark = true;
                    }
                }
                if (hasMark) { foundTiles.add(tile); }
            }
        }
        groundMarkTiles = Collections.unmodifiableList(foundTiles);
        groundMarkCount = foundCount;
        groundMarkScanValid = scannedCourseTile;
    }

    private void resetMarks()
    {
        groundMarkTiles = Collections.emptyList();
        groundMarkCount = 0;
        groundMarkScanValid = false;
    }

    static boolean shouldHighlightMarks(int count, int threshold)
    {
        return count >= Math.max(1, threshold);
    }

    boolean isInArdougne()
    {
        Player player = client.getLocalPlayer();
        return player != null && player.getWorldLocation() != null && player.getWorldLocation().getRegionID() == REGION;
    }

    /** Current player plane only when logged in within the supported Ardougne course region. */
    int coursePlane()
    {
        if (client.getGameState() != GameState.LOGGED_IN) { return -1; }
        Player player = client.getLocalPlayer();
        if (player == null) { return -1; }
        WorldPoint at = player.getWorldLocation();
        return at != null && at.getRegionID() == REGION ? at.getPlane() : -1;
    }

    private boolean isMarkPriorityEnabled()
    {
        return config.prioritizeMarks() && config.highlightMarks();
    }

    boolean isMarkPrioritySuppressingHulls()
    {
        return isMarkPriorityEnabled() && markPriority.suppressObstacleHulls();
    }

    boolean isExclusiveMarkMode()
    {
        return isMarkPriorityEnabled() && markPriority.showExclusiveMarks();
    }

    boolean isPlayerMoving() { return motionTracker.isMoving(); }

    int groundMarkCount() { return groundMarkCount; }
    List<Tile> groundMarkTiles() { return groundMarkTiles; }

    // Always follow the automatic tracker. There is no manual stage override.
    int selectedStage() { return tracker.getStage(); }

    // The preview is always gated by a genuine obstacle click plus movement.
    boolean isGhostPreviewActive()
    {
        return config.showGhostPreview() && previewGate.isActiveFor(selectedStage());
    }

    boolean hasVisibleSelectedObject() { return hasVisibleStageObject(selectedStage()); }

    TileObject selectedObject()
    {
        return objectForStage(selectedStage(), true);
    }

    /** Resolve a stage's object; future previews do not require a live clickbox. */
    TileObject objectForStage(int stage, boolean requireLiveClickbox)
    {
        if (stage < 0 || stage >= IDS.length) { return null; }
        Player player = client.getLocalPlayer();
        if (player == null || player.getWorldLocation() == null || player.getWorldLocation().getRegionID() != REGION) { return null; }
        TileObject best = null;
        int bestDistance = Integer.MAX_VALUE;
        for (Map.Entry<TileObject,Integer> entry : objects.entrySet())
        {
            if (entry.getValue() != stage) { continue; }
            TileObject o = entry.getKey();
            if (o.getWorldLocation() == null || (requireLiveClickbox && o.getClickbox() == null)) { continue; }
            int distance = o.getWorldLocation().distanceTo2D(player.getWorldLocation());
            if (distance < bestDistance)
            {
                bestDistance = distance;
                best = o;
            }
        }
        return best;
    }
}

package com.ardougnehelper;

import java.util.Map;
import java.util.TreeMap;

/**
 * Diagnostics ONLY for an attempted obstacle-5 -> obstacle-6 preview.
 * Observes gate and render outcomes but cannot change controller decisions.
 */
final class ArdougnePreview5Audit
{
    private boolean tracking;
    private int startedTick;
    private int sampledTicks;
    private int renderFrames;
    private int pendingFrames;
    private int activeFrames;
    private int onscreenFrames;
    private int offscreenFrames;
    private int noShapeFrames;
    private boolean everActive;
    private boolean everPending;
    private final Map<String, Integer> reasons = new TreeMap<>();

    synchronized void reset()
    {
        tracking = false;
        startedTick = -1;
        sampledTicks = 0;
        renderFrames = 0;
        pendingFrames = 0;
        activeFrames = 0;
        onscreenFrames = 0;
        offscreenFrames = 0;
        noShapeFrames = 0;
        everActive = false;
        everPending = false;
        reasons.clear();
    }

    synchronized void start(int tick)
    {
        reset();
        tracking = true;
        startedTick = tick;
    }

    synchronized boolean isTracking() { return tracking; }

    synchronized void observeGate(boolean pending, boolean active)
    {
        if (!tracking) { return; }
        sampledTicks++;
        everPending |= pending;
        everActive |= active;
    }

    synchronized void observeRender(boolean pending, boolean active, boolean shape,
        boolean onscreen, String reason)
    {
        if (!tracking) { return; }
        renderFrames++;
        if (pending) { pendingFrames++; }
        if (active) { activeFrames++; }
        everPending |= pending;
        everActive |= active;
        if (shape)
        {
            if (onscreen) { onscreenFrames++; }
            else { offscreenFrames++; }
        }
        else
        {
            noShapeFrames++;
        }
        String key = reason == null ? "UNKNOWN" : reason;
        reasons.put(key, reasons.getOrDefault(key, 0) + 1);
    }

    synchronized String finish(String outcome, int endingTick)
    {
        if (!tracking) { return null; }
        String verdict;
        if (onscreenFrames > 0)
        {
            verdict = "PREVIEW_RENDERED";
        }
        else if (activeFrames == 0 && !everActive)
        {
            verdict = "DEPARTURE_GATE_NOT_CONFIRMED";
        }
        else if (offscreenFrames > 0)
        {
            verdict = "PROJECTED_OFFSCREEN";
        }
        else if (renderFrames == 0)
        {
            verdict = "NO_RENDER_FRAMES";
        }
        else
        {
            verdict = "PROJECTION_UNAVAILABLE";
        }
        String result = "outcome=" + outcome + " ticks=" + (endingTick - startedTick) +
            " verdict=" + verdict + " observedTicks=" + sampledTicks +
            " everPending=" + everPending + " everActive=" + everActive +
            " renderFrames=" + renderFrames + " pendingFrames=" + pendingFrames +
            " activeFrames=" + activeFrames + " onscreenFrames=" + onscreenFrames +
            " offscreenFrames=" + offscreenFrames + " noShapeFrames=" + noShapeFrames +
            " reasons=" + reasons;
        reset();
        return result;
    }
}

package com.ardougnehelper;

/**
 * Controls when the next-obstacle preview may replace the cyan current hull.
 * An actual interaction with the selected obstacle MUST precede observable
 * departure: a position change or a newly started actor animation. Sampling
 * on client ticks avoids missing short traversals that begin and award XP
 * entirely between two 600 ms game ticks.
 *
 * A click alone is not completion; stage changes still require the course
 * tracker's XP/position evidence and reset this preview independently.
 */
final class ArdougnePreviewGate
{
    static final int MAX_CONFIRM_TICKS = 10;
    // A confirmed departure can span several actor animation phases; this
    // bounded window prevents a missed XP event causing permanent yellow.
    static final int MAX_IN_FLIGHT_TICKS = 16;
    private static final int UNKNOWN_LOCAL = Integer.MIN_VALUE;

    private int pendingStage = -1;
    private int pendingTick;
    private int originX;
    private int originY;
    private int originPlane;
    private int originLocalX = UNKNOWN_LOCAL;
    private int originLocalY = UNKNOWN_LOCAL;
    private int clickActionAnimation = -1;
    private int clickPoseAnimation = -1;
    private boolean walkingAtClick;
    private int activeStage = -1;
    private int activeTick = -1;

    void reset()
    {
        pendingStage = -1;
        activeStage = -1;
        activeTick = -1;
    }

    /** Compatibility overload used for game-tick-only behavior and tests. */
    void onValidObstacleClick(int clickedStage, int selectedStage, int tick, int x, int y, int plane)
    {
        onValidObstacleClick(clickedStage, selectedStage, tick, x, y, plane,
            UNKNOWN_LOCAL, UNKNOWN_LOCAL, -1, -1, -1);
    }

    /** Caller must verify genuine object interaction, matching stage, and ID. */
    void onValidObstacleClick(int clickedStage, int selectedStage, int tick, int x, int y,
        int plane, int localX, int localY, int actionAnimation, int poseAnimation,
        int idlePoseAnimation)
    {
        if (clickedStage < 0 || clickedStage >= ArdougneCourseTracker.STAGE_COUNT ||
            clickedStage != selectedStage)
        {
            return;
        }
        if (activeStage == selectedStage)
        {
            // Re-clicking a confirmed obstacle does not blank the preview.
            return;
        }
        pendingStage = clickedStage;
        pendingTick = tick;
        originX = x;
        originY = y;
        originPlane = plane;
        originLocalX = localX;
        originLocalY = localY;
        clickActionAnimation = actionAnimation;
        clickPoseAnimation = poseAnimation;
        walkingAtClick = poseAnimation >= 0 && idlePoseAnimation >= 0 &&
            poseAnimation != idlePoseAnimation;
    }

    /** Existing game-tick position verification remains as a safe fallback. */
    void onTick(int currentStage, int tick, int x, int y, int plane)
    {
        observe(currentStage, tick, x, y, plane, UNKNOWN_LOCAL, UNKNOWN_LOCAL,
            -1, -1, -1);
    }

    /**
     * Faster evidence from the player actor. The animation must have STARTED
     * after the click; pre-existing animation is not authorization. No shape
     * or target is inferred here: only the existing ghost projection can draw.
     */
    void onClientActivity(int currentStage, int tick, int x, int y, int plane,
        int localX, int localY, int actionAnimation, int poseAnimation, int idlePoseAnimation)
    {
        observe(currentStage, tick, x, y, plane, localX, localY,
            actionAnimation, poseAnimation, idlePoseAnimation);
    }

    private void observe(int currentStage, int tick, int x, int y, int plane,
        int localX, int localY, int actionAnimation, int poseAnimation, int idlePoseAnimation)
    {
        if (currentStage < 0 || currentStage >= ArdougneCourseTracker.STAGE_COUNT)
        {
            reset();
            return;
        }
        if (activeStage >= 0 && (currentStage != activeStage ||
            tick < activeTick || tick - activeTick > MAX_IN_FLIGHT_TICKS))
        {
            // The current stage never advanced: a stalled/failed traversal
            // must eventually restore clickable cyan rather than keep an
            // orange preview (or yellow HUD) indefinitely.
            reset();
        }
        if (pendingStage < 0)
        {
            return;
        }
        if (pendingStage != currentStage || tick < pendingTick ||
            tick - pendingTick > MAX_CONFIRM_TICKS)
        {
            pendingStage = -1;
            return;
        }

        boolean worldMoved = x != originX || y != originY || plane != originPlane;
        boolean localMoved = originLocalX != UNKNOWN_LOCAL &&
            localX != UNKNOWN_LOCAL && (localX != originLocalX || localY != originLocalY);
        boolean animationStarted = actionAnimation >= 0 &&
            actionAnimation != clickActionAnimation;
        boolean walkingStarted = poseAnimation >= 0 && idlePoseAnimation >= 0 &&
            poseAnimation != idlePoseAnimation &&
            (!walkingAtClick || poseAnimation != clickPoseAnimation);
        if (worldMoved || localMoved || animationStarted || walkingStarted)
        {
            activeStage = currentStage;
            activeTick = tick;
            pendingStage = -1;
        }
    }

    boolean isActiveFor(int currentStage)
    {
        return currentStage >= 0 && activeStage == currentStage;
    }

    boolean isPendingFor(int currentStage)
    {
        return currentStage >= 0 && pendingStage == currentStage;
    }
    /** Bounded, movement-confirmed traversal activity for the yellow HUD. */
    boolean isInFlightFor(int currentStage, int tick)
    {
        return isActiveFor(currentStage) && activeTick >= 0 &&
            tick >= activeTick && tick - activeTick <= MAX_IN_FLIGHT_TICKS;
    }

}

package com.ardougnehelper;

/**
 * The cyan hull marks the obstacle to click now. The projected orange hull
 * marks the FOLLOWING obstacle, as seen from the current obstacle's landing.
 * Keeping this mapping separate prevents the two overlays from silently
 * selecting the same stage again.
 */
final class ArdougnePreviewPlan
{
    private ArdougnePreviewPlan() { }

    static int followingStage(int selectedStage)
    {
        if (selectedStage < 0 || selectedStage >= ArdougneCourseTracker.STAGE_COUNT)
        {
            return -1;
        }
        return (selectedStage + 1) % ArdougneCourseTracker.STAGE_COUNT;
    }
}

package com.ardougnehelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LineComponent;

/** Compact HUD. Stage/debug information is intentionally not displayed. */
public class ArdougneStageOverlay extends OverlayPanel
{
    private final ArdougnePlugin plugin;
    private final ArdougneConfig config;

    @Inject public ArdougneStageOverlay(ArdougnePlugin plugin, ArdougneConfig config)
    {
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
    }

    @Override public Dimension render(Graphics2D graphics)
    {
        if (!config.enableHud() || !plugin.isInArdougne())
        {
            return null;
        }

        // Preserve RuneLite's standard background color and adjust only alpha.
        Color stock = ComponentConstants.STANDARD_BACKGROUND_COLOR;
        int alpha = Math.max(0, Math.min(255, config.hudBackgroundOpacity()));
        panelComponent.setBackgroundColor(new Color(stock.getRed(), stock.getGreen(), stock.getBlue(), alpha));
        panelComponent.getChildren().clear();

        if (config.friendlyTaunt())
        {
            int plane = plugin.coursePlane();
            if (ArdougneTauntHeader.textForPlane(plane) != null)
            {
                panelComponent.getChildren().add(new ArdougneTauntHeader(plane, plugin.isPlayerMoving()));
            }
        }

        // Always count ground marks, even when the highlight threshold is not met.
        panelComponent.getChildren().add(LineComponent.builder()
            .left("Marks on ground")
            .right(Integer.toString(plugin.groundMarkCount()))
            .build());

        if (config.showRunCounters())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Laps")
                .right(Integer.toString(plugin.lapCount()))
                .build());
        }
        if (config.showFallCount())
        {
            panelComponent.getChildren().add(LineComponent.builder()
                .left("Falls")
                .right(Integer.toString(plugin.fallCount()))
                .build());
        }
        return super.render(graphics);
    }
}

package com.ardougnehelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import net.runelite.client.ui.overlay.components.ComponentConstants;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/** A single HUD row: red at rest on ground, yellow during movement, standard on roofs. */
final class ArdougneTauntHeader implements LayoutableRenderableEntity
{
    static final Color GROUND_COLOR = new Color(255, 0, 0, 255);
    static final Color MOVING_COLOR = new Color(255, 212, 0, 255);
    static final String GROUND_TEXT = "Don't give up!";
    static final String ROOFTOP_TEXT = "Isn't this fun?";
    static final String MOVING_TEXT = "I believe in you!";

    private final int plane;
    private final boolean moving;
    private final Rectangle bounds = new Rectangle();
    private Point preferredLocation = new Point();
    private Dimension preferredSize = new Dimension(ComponentConstants.STANDARD_WIDTH, 0);

    ArdougneTauntHeader(int plane)
    {
        this(plane, false);
    }

    ArdougneTauntHeader(int plane, boolean moving)
    {
        this.plane = plane;
        this.moving = moving;
    }

    /** Return null for an unverified plane (or when outside the supported area). */
    static String textForPlane(int plane)
    {
        if (plane == 0) { return GROUND_TEXT; }
        if (plane >= 1 && plane <= 3) { return ROOFTOP_TEXT; }
        return null;
    }

    static String textForState(int plane, boolean moving)
    {
        String stationary = textForPlane(plane);
        return stationary == null ? null : (moving ? MOVING_TEXT : stationary);
    }

    @Override public void setPreferredLocation(Point location)
    {
        preferredLocation = location;
    }

    @Override public void setPreferredSize(Dimension size)
    {
        preferredSize = size;
    }

    @Override public Rectangle getBounds()
    {
        return bounds;
    }

    @Override public Dimension render(Graphics2D graphics)
    {
        String message = textForState(plane, moving);
        if (message == null)
        {
            bounds.setBounds(preferredLocation.x, preferredLocation.y, 0, 0);
            return new Dimension();
        }

        FontMetrics fm = graphics.getFontMetrics();
        int rowHeight = fm.getHeight() + 6;
        int width = Math.max(0, preferredSize.width);
        int x = preferredLocation.x;
        int y = preferredLocation.y;
        Color oldColor = graphics.getColor();

        if (moving || plane == 0)
        {
            // Cover the entire HUD header including the standard four-pixel panel border.
            // The colored header stays opaque even if the rest of the HUD is transparent.
            int border = ComponentConstants.STANDARD_BORDER;
            int left = x - border;
            int top = y - border;
            int fullWidth = width + 2 * border;
            int fullHeight = rowHeight + border;
            graphics.setColor(moving ? MOVING_COLOR : GROUND_COLOR);
            graphics.fillRect(left, top, fullWidth, fullHeight);
            graphics.setColor(Color.BLACK);
            graphics.drawRect(left, top, fullWidth - 1, fullHeight - 1);
            graphics.setColor(Color.BLACK);
        }
        else
        {
            // Do not paint a second background: use the normal HUD color/opacity.
            graphics.setColor(Color.WHITE);
        }

        int textX = x + Math.max(0, (width - fm.stringWidth(message)) / 2);
        int textY = y + (rowHeight - fm.getHeight()) / 2 + fm.getAscent();
        graphics.drawString(message, textX, textY);
        graphics.setColor(oldColor);

        bounds.setBounds(x, y, width, rowHeight);
        return new Dimension(width, rowHeight);
    }
}

