package com.ardougnehelper;

/**
 * Pure state tracking for the seven Ardougne rooftop obstacles. It deliberately
 * does not infer a successful lap or fall from a click/animation alone.
 *
 * A lap needs the final obstacle's XP reward. A fall needs confirmed rooftop
 * progress followed by three consecutive ground-level game ticks. Landing at
 * the course's known finish without receiving the final XP is considered
 * unverified (not a fall). This favors accurate counters over guessing.
 */
final class ArdougneCourseTracker
{
    enum Event
    {
        NONE, ADVANCED, LAP, FALL, RECOVERED, INTERRUPTED, UNVERIFIED_FINISH
    }

    static final int[] OBSTACLE_XP = {43, 65, 50, 21, 28, 57, 625};
    static final int STAGE_COUNT = OBSTACLE_XP.length;
    static final int FALL_CONFIRM_TICKS = 3;
    static final int FINISH_CONFIRM_TICKS = 6;
    static final int COURSE_FINISH_X = 2668;
    static final int COURSE_FINISH_Y = 3297;
    private static final int FINISH_RADIUS = 5;
    private static final int MAX_PLAUSIBLE_FALL_DISTANCE = 18;

    private int stage = -1;
    private int laps;
    private int falls;
    private int groundTicks;
    private int lastRooftopX;
    private int lastRooftopY;
    private boolean hasLastRooftopPosition;
    private boolean visitedRooftop;
    private boolean activeRun;

    int getStage() { return stage; }
    int getLaps() { return laps; }
    int getFalls() { return falls; }

    /** Reset stage across a scene load or login, without erasing session totals. */
    Event onSceneLoading()
    {
        boolean interrupted = activeRun;
        clearRun(-1);
        return interrupted ? Event.INTERRUPTED : Event.NONE;
    }

    void clearSession()
    {
        clearRun(-1);
        laps = 0;
        falls = 0;
    }

    /**
     * Called once each game tick, after any movement for the tick. The inferred
     * stage is a fallback estimate from nearby objects (or -1 if unknown).
     */
    Event onPosition(boolean inRegion, int x, int y, int plane, int inferredStage)
    {
        if (!inRegion)
        {
            boolean interrupted = activeRun;
            clearRun(-1);
            return interrupted ? Event.INTERRUPTED : Event.NONE;
        }

        if (stage < 0)
        {
            if (plane == 0)
            {
                stage = 0;
            }
            else if (validStage(inferredStage))
            {
                stage = inferredStage;
                activeRun = stage > 0;
                visitedRooftop = true;
                rememberRooftop(x, y);
                return Event.RECOVERED;
            }
        }

        if (plane > 0)
        {
            visitedRooftop = true;
            rememberRooftop(x, y);
            groundTicks = 0;
            // If XP tracking was initialized too late, recover from the visible
            // location instead of permanently highlighting the starting beams.
            if (stage == 0 && !activeRun && validStage(inferredStage) && inferredStage > 0)
            {
                stage = inferredStage;
                activeRun = true;
                return Event.RECOVERED;
            }
            return Event.NONE;
        }

        if (stage < 1 || !activeRun)
        {
            groundTicks = 0;
            stage = 0;
            return Event.NONE;
        }

        // A teleport within the same map region can change floors instantly.
        // Don't mistake a large horizontal jump for falling off an obstacle.
        if (hasLastRooftopPosition &&
            (Math.abs(x - lastRooftopX) > MAX_PLAUSIBLE_FALL_DISTANCE ||
             Math.abs(y - lastRooftopY) > MAX_PLAUSIBLE_FALL_DISTANCE))
        {
            clearRun(0);
            return Event.INTERRUPTED;
        }

        if (!visitedRooftop)
        {
            // A first-obstacle XP event may arrive before a rooftop position
            // is sampled. Do not claim a fall without observing the roof.
            clearRun(0);
            return Event.INTERRUPTED;
        }

        groundTicks++;

        if (stage == STAGE_COUNT - 1 && nearFinish(x, y))
        {
            // The final obstacle transitions to the ground. The final XP can
            // arrive after the position update, so give it time to arrive.
            if (groundTicks >= FINISH_CONFIRM_TICKS)
            {
                clearRun(0);
                return Event.UNVERIFIED_FINISH;
            }
            return Event.NONE;
        }

        if (groundTicks >= FALL_CONFIRM_TICKS)
        {
            falls++;
            clearRun(0);
            return Event.FALL;
        }
        return Event.NONE;
    }

    /**
     * Called only for a *new* positive Agility XP delta. Each course obstacle
     * awards a distinct amount, permitting recovery if a previous XP event was
     * missed or the inferred stage was wrong.
     */
    Event onExperienceGain(int gain, boolean inRegion, int plane)
    {
        if (!inRegion || gain <= 0)
        {
            return Event.NONE;
        }
        int completed = stageForExperience(gain);
        if (completed < 0)
        {
            return Event.NONE;
        }

        // Reject a repeated/older event or arbitrary off-course XP. The final
        // obstacle can award its XP after the player lands on plane 0.
        if (stage >= 0 && completed < stage)
        {
            return Event.NONE;
        }
        if (completed > 0 && completed != stage && !visitedRooftop && plane == 0)
        {
            return Event.NONE;
        }

        groundTicks = 0;
        if (completed == STAGE_COUNT - 1)
        {
            laps++;
            clearRun(0);
            return Event.LAP;
        }

        stage = completed + 1;
        activeRun = true;
        if (plane > 0)
        {
            visitedRooftop = true;
        }
        return Event.ADVANCED;
    }

    private static boolean validStage(int candidate)
    {
        return candidate >= 0 && candidate < STAGE_COUNT;
    }

    private static boolean nearFinish(int x, int y)
    {
        return Math.abs(x - COURSE_FINISH_X) <= FINISH_RADIUS
            && Math.abs(y - COURSE_FINISH_Y) <= FINISH_RADIUS;
    }

    private static int stageForExperience(int gain)
    {
        for (int i = 0; i < OBSTACLE_XP.length; i++)
        {
            if (OBSTACLE_XP[i] == gain)
            {
                return i;
            }
        }
        return -1;
    }

    private void rememberRooftop(int x, int y)
    {
        lastRooftopX = x;
        lastRooftopY = y;
        hasLastRooftopPosition = true;
    }

    private void clearRun(int newStage)
    {
        stage = newStage;
        activeRun = false;
        visitedRooftop = false;
        groundTicks = 0;
        hasLastRooftopPosition = false;
    }
}

