package com.ardougnehelper;

import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import org.junit.Test;
import static org.junit.Assert.*;

public class ArdougneConfigTest
{
    @Test public void hasFourOrderedCollapsibleSections() throws Exception
    {
        String[] fields = {"obstacleSettings", "previewSettings", "marksSettings", "hudSettings"};
        String[] labels = {"Obstacle Settings", "Preview Settings", "Marks of Grace", "HUD Settings"};
        for (int i = 0; i < fields.length; i++)
        {
            Field f = ArdougneConfig.class.getField(fields[i]);
            ConfigSection section = f.getAnnotation(ConfigSection.class);
            assertNotNull(section);
            assertEquals(labels[i], section.name());
            assertEquals(i, section.position());
            assertEquals(i != 0, section.closedByDefault());
        }
    }

    @Test public void everyVisibleSettingIsInItsRequestedSection() throws Exception
    {
        expect("hullColor", "Obstacle hull color", "obstacleSettings");
        expect("fillAlpha", "Fill opacity", "obstacleSettings");
        expect("showGhostPreview", "Next obstacle preview", "previewSettings");
        expect("ghostColor", "Preview hull color", "previewSettings");
        expect("ghostFillAlpha", "Preview fill opacity", "previewSettings");
        expect("highlightMarks", "Highlight Marks of Grace", "marksSettings");
        expect("markColor", "Mark highlight color", "marksSettings");
        expect("minimumGroundMarks", "Highlight threshold", "marksSettings");
        expect("prioritizeMarks", "Prioritize Marks of Grace", "marksSettings");
        expect("enableHud", "Enable HUD", "hudSettings");
        expect("hudBackgroundOpacity", "Background opacity", "hudSettings");
        expect("showRunCounters", "Show laps", "hudSettings");
        expect("showFallCount", "Show falls", "hudSettings");
        expect("friendlyTaunt", "Friendly taunt", "hudSettings");

        int count = 0;
        for (Method m : ArdougneConfig.class.getDeclaredMethods())
        {
            if (m.getAnnotation(ConfigItem.class) != null)
            {
                count++;
            }
        }
        assertEquals("No obsolete settings should appear in the UI", 14, count);
    }

    @Test public void requiredDefaultsAndNoRetiredSettings() throws Exception
    {
        ArdougneConfig config = new ArdougneConfig() {};
        assertTrue(config.enableHud());
        assertTrue(config.showRunCounters());
        assertFalse(config.showFallCount());
        assertFalse(config.friendlyTaunt());
        assertTrue(config.showGhostPreview());
        assertFalse(config.prioritizeMarks());
        assertEquals(1, config.minimumGroundMarks());
        Set<String> retired = new HashSet<>(Arrays.asList("showDebug", "manualStage", "showMarkCount",
            "previewAfterClick", "singleObstacleHull", "showFalls"));
        for (Method method : ArdougneConfig.class.getDeclaredMethods())
        {
            assertFalse("Obsolete settings must not remain: " + method.getName(),
                retired.contains(method.getName()));
        }
    }

    private static void expect(String methodName, String label, String sectionName) throws Exception
    {
        ConfigItem item = ArdougneConfig.class.getMethod(methodName).getAnnotation(ConfigItem.class);
        assertNotNull("Missing config item " + methodName, item);
        assertEquals(label, item.name());
        assertEquals(sectionName, item.section());
    }
}

