package com.ardougnehelper;

import org.junit.Test;
import static org.junit.Assert.*;

/** Regression cases for a HUD-only fix: no course/preview ownership. */
public class ArdougneFirstObstacleHudXpTest
{
    private static final long T = 1_000_000_000L;

    @Test public void recoveredStageBeforeXpAllowsOneHudOnlyFirstCompletion()
    {
        ArdougneCourseTracker stages = new ArdougneCourseTracker();
        ArdougneFirstObstacleHudXp gate = new ArdougneFirstObstacleHudXp();
        stages.onPosition(true, 2670, 3290, 0, 0);
        gate.onValidObstacleClick(stages.getStage(), 0, T);
        gate.observe(true, stages.getStage(), 2, T + 100_000_000L);
        ArdougneCourseTracker.Event recovered = stages.onPosition(true, 2672, 3295, 3, 1);
        assertEquals(ArdougneCourseTracker.Event.RECOVERED, recovered);
        assertEquals(1, stages.getStage());
        gate.onCourseEvent(recovered, stages.getStage());
        gate.observe(true, stages.getStage(), 3, T + 200_000_000L);
        ArdougneCourseTracker.Event xp = stages.onExperienceGain(43, true, 3);
        assertEquals("v0.2.9 intentionally rejects older XP after position recovery",
            ArdougneCourseTracker.Event.NONE, xp);
        assertTrue("HUD may independently acknowledge it once", gate.consumeHudOnlyXp(
            43, true, stages.getStage(), 3, xp, T + 300_000_000L));
        assertEquals("HUD-only confirmation must not change course stage", 1, stages.getStage());
        assertFalse("cannot reuse a 43 XP event", gate.consumeHudOnlyXp(
            43, true, stages.getStage(), 3, xp, T + 400_000_000L));
    }

    @Test public void hudOnlyXpRemovesLongHoldWhileStageAndPreviewRemainIdenticalToBaseline()
    {
        ArdougneCourseTracker baseline = new ArdougneCourseTracker();
        ArdougneCourseTracker patched = new ArdougneCourseTracker();
        ArdougnePreviewGate oldPreview = new ArdougnePreviewGate();
        ArdougnePreviewGate newPreview = new ArdougnePreviewGate();
        ArdougneMotionTracker beforeHud = new ArdougneMotionTracker();
        ArdougneMotionTracker afterHud = new ArdougneMotionTracker();
        ArdougneFirstObstacleHudXp hudGate = new ArdougneFirstObstacleHudXp();
        long now = 4_000_000_000L;

        assertEquals(baseline.onPosition(true, 2670, 3290, 0, 0),
            patched.onPosition(true, 2670, 3290, 0, 0));
        beforeHud.observe(true, 1, 1, 2670, 3290, 0, 1, 1, -1, now);
        afterHud.observe(true, 1, 1, 2670, 3290, 0, 1, 1, -1, now);
        hudGate.onValidObstacleClick(0, 0, now);
        oldPreview.onValidObstacleClick(0, 0, 10, 2670, 3290, 0,
            1, 1, -1, 1, 1);
        newPreview.onValidObstacleClick(0, 0, 10, 2670, 3290, 0,
            1, 1, -1, 1, 1);
        assertFalse(oldPreview.isActiveFor(0));
        assertEquals(oldPreview.isActiveFor(0), newPreview.isActiveFor(0));

        // Both baselines show the same orange preview after the valid departure.
        oldPreview.onClientActivity(0, 10, 2670, 3290, 2,
            5, 5, 812, 1, 1);
        newPreview.onClientActivity(0, 10, 2670, 3290, 2,
            5, 5, 812, 1, 1);
        assertTrue(oldPreview.isActiveFor(0));
        assertEquals(oldPreview.isActiveFor(0), newPreview.isActiveFor(0));
        beforeHud.observe(true, 5, 5, 2670, 3290, 2, 1, 1, 812,
            now + 200_000_000L, true);
        afterHud.observe(true, 5, 5, 2670, 3290, 2, 1, 1, 812,
            now + 200_000_000L, true);
        hudGate.observe(true, 0, 2, now + 200_000_000L);

        // Stage recovery (before XP) is unchanged. Cyan obstacle 2 begins
        // here, not when the delayed 43 XP is processed.
        ArdougneCourseTracker.Event oldRecovery =
            baseline.onPosition(true, 2672, 3295, 3, 1);
        ArdougneCourseTracker.Event newRecovery =
            patched.onPosition(true, 2672, 3295, 3, 1);
        assertEquals(ArdougneCourseTracker.Event.RECOVERED, oldRecovery);
        assertEquals(oldRecovery, newRecovery);
        oldPreview.reset();
        newPreview.reset();
        hudGate.onCourseEvent(newRecovery, patched.getStage());
        hudGate.observe(true, patched.getStage(), 3, now + 300_000_000L);
        assertEquals("cyan obstacle 2 becomes eligible simultaneously",
            baseline.getStage(), patched.getStage());
        assertEquals(1, patched.getStage());
        assertFalse(oldPreview.isActiveFor(1));
        assertEquals(oldPreview.isActiveFor(1), newPreview.isActiveFor(1));

        beforeHud.observe(true, 5, 5, 2672, 3295, 3, 1, 1, -1,
            now + 400_000_000L, false);
        afterHud.observe(true, 5, 5, 2672, 3295, 3, 1, 1, -1,
            now + 400_000_000L, false);
        assertTrue(beforeHud.isMoving());
        assertTrue(afterHud.isMoving());

        ArdougneCourseTracker.Event oldXp = baseline.onExperienceGain(43, true, 3);
        ArdougneCourseTracker.Event newXp = patched.onExperienceGain(43, true, 3);
        assertEquals(oldXp, newXp);
        assertEquals(ArdougneCourseTracker.Event.NONE, newXp);
        assertTrue(hudGate.consumeHudOnlyXp(43, true, patched.getStage(), 3,
            newXp, now + 500_000_000L));
        // Only the new HUD receives confirmation; no gate reset or stage change.
        afterHud.onConfirmedCourseXp(true, 5, 5, 2672, 3295, 3,
            1, 1, -1, now + 500_000_000L, 0);
        assertEquals(baseline.getStage(), patched.getStage());
        assertEquals(oldPreview.isActiveFor(1), newPreview.isActiveFor(1));
        assertTrue("old implementation is delayed", beforeHud.isMoving());
        afterHud.observe(true, 5, 5, 2672, 3295, 3, 1, 1, -1,
            now + 620_000_000L, false);
        assertFalse("new HUD returns grey quickly after the late XP", afterHud.isMoving());
        beforeHud.observe(true, 5, 5, 2672, 3295, 3, 1, 1, -1,
            now + 620_000_000L, false);
        assertTrue("old HUD is still serving its 1.3-second hold", beforeHud.isMoving());

        // Obstacle 2's accepted XP still advances both trackers identically.
        assertEquals(baseline.onExperienceGain(65, true, 3),
            patched.onExperienceGain(65, true, 3));
        assertEquals(2, patched.getStage());
        assertEquals(baseline.getStage(), patched.getStage());
    }

    @Test public void ordinaryXpBeforePositionRecoveryStillUsesExistingPath()
    {
        ArdougneCourseTracker stages = new ArdougneCourseTracker();
        ArdougneFirstObstacleHudXp gate = new ArdougneFirstObstacleHudXp();
        stages.onPosition(true, 2670, 3290, 0, 0);
        gate.onValidObstacleClick(0, 0, T);
        ArdougneCourseTracker.Event normalXp = stages.onExperienceGain(43, true, 3);
        assertEquals(ArdougneCourseTracker.Event.ADVANCED, normalXp);
        assertFalse("no duplicate HUD-only callback on normally accepted XP",
            gate.consumeHudOnlyXp(43, true, stages.getStage(), 3,
                normalXp, T + 200_000_000L));
        assertEquals(1, stages.getStage());
    }

    @Test public void noClickOrOtherObstacleClickCannotAuthorizeFallback()
    {
        ArdougneFirstObstacleHudXp gate = new ArdougneFirstObstacleHudXp();
        assertFalse(gate.consumeHudOnlyXp(43, true, 1, 3,
            ArdougneCourseTracker.Event.NONE, T));
