        assertFalse(gate.consumeHudOnlyXp(43, true, 1, 3,
            ArdougneCourseTracker.Event.NONE, T + 1));
        gate.onValidObstacleClick(0, 3, T);
        assertFalse("first-click arming requires ground plane 0",
            gate.consumeHudOnlyXp(43, true, 1, 3,
