        gate.onValidObstacleClick(0, 0, T);
        assertFalse(gate.consumeHudOnlyXp(43, true, 1, 0,
            ArdougneCourseTracker.Event.NONE, T + 1));
        gate.onValidObstacleClick(0, 0, T);
        gate.observe(true, 0, 2, T + 1);
        assertFalse("plane 2 is an intermediate plane, not completed landing",
            gate.consumeHudOnlyXp(43, true, 1, 2,
