        gate.onValidObstacleClick(0, 0, T);
        gate.observe(true, 0, 3, T + 1);
        assertFalse(gate.consumeHudOnlyXp(43, true, 0, 3,
            ArdougneCourseTracker.Event.NONE, T + 2));
        gate.onValidObstacleClick(0, 0, T);
        gate.observe(true, 0, 3, T + 1);
        assertFalse(gate.consumeHudOnlyXp(43, true, 2, 3,
            ArdougneCourseTracker.Event.NONE, T + 2));
    }

    @Test public void firstXpOnPlane3BeforeEarlierObservationMayStillBeRecognized()
    {
        ArdougneFirstObstacleHudXp gate = new ArdougneFirstObstacleHudXp();
        gate.onValidObstacleClick(0, 0, T);
        // The real XP callback is allowed to supply the first observed plane 3.
        gate.observe(true, 1, 3, T + 1);
        assertTrue(gate.consumeHudOnlyXp(43, true, 1, 3,
            ArdougneCourseTracker.Event.NONE, T + 2));
    }

    @Test public void wrongExperienceDeltaRejectedAndConsumed()
    {
        ArdougneFirstObstacleHudXp gate = new ArdougneFirstObstacleHudXp();
        gate.onValidObstacleClick(0, 0, T);
        gate.observe(true, 1, 3, T + 1);
        assertFalse(gate.consumeHudOnlyXp(65, true, 1, 3,
            ArdougneCourseTracker.Event.NONE, T + 2));
        assertFalse(gate.consumeHudOnlyXp(43, true, 1, 3,
            ArdougneCourseTracker.Event.NONE, T + 3));
    }

    @Test public void clickWindowExpiresAndCannotRearmWithoutAnotherValidClick()
    {
        ArdougneFirstObstacleHudXp gate = new ArdougneFirstObstacleHudXp();
        gate.onValidObstacleClick(0, 0, T);
        gate.observe(true, 1, 3, T + ArdougneFirstObstacleHudXp.MAX_CLICK_TO_XP_NANOS);
        assertTrue("exact boundary is still eligible", gate.consumeHudOnlyXp(
            43, true, 1, 3, ArdougneCourseTracker.Event.NONE,
            T + ArdougneFirstObstacleHudXp.MAX_CLICK_TO_XP_NANOS));
        gate.onValidObstacleClick(0, 0, T);
        gate.observe(true, 1, 3, T + ArdougneFirstObstacleHudXp.MAX_CLICK_TO_XP_NANOS + 1);
        assertFalse("stale click cannot accept XP", gate.consumeHudOnlyXp(
            43, true, 1, 3, ArdougneCourseTracker.Event.NONE,
            T + ArdougneFirstObstacleHudXp.MAX_CLICK_TO_XP_NANOS + 2));
    }

    @Test public void sceneChangeTeleportAndFallCancelPendingClaim()
    {
        ArdougneFirstObstacleHudXp gate = new ArdougneFirstObstacleHudXp();
        gate.onValidObstacleClick(0, 0, T);
        gate.onCourseEvent(ArdougneCourseTracker.Event.INTERRUPTED, -1);
        assertFalse(gate.consumeHudOnlyXp(43, true, 1, 3,
            ArdougneCourseTracker.Event.NONE, T + 1));
        gate.onValidObstacleClick(0, 0, T);
        gate.observe(false, 1, 3, T + 1);
        assertFalse(gate.consumeHudOnlyXp(43, true, 1, 3,
            ArdougneCourseTracker.Event.NONE, T + 2));
        gate.onValidObstacleClick(0, 0, T);
        gate.onCourseEvent(ArdougneCourseTracker.Event.FALL, 0);
        assertFalse(gate.consumeHudOnlyXp(43, true, 1, 3,
            ArdougneCourseTracker.Event.NONE, T + 1));
    }

    @Test public void unrelatedStageRecoveryCancelsPendingClaim()
    {
        ArdougneFirstObstacleHudXp gate = new ArdougneFirstObstacleHudXp();
        gate.onValidObstacleClick(0, 0, T);
        gate.onCourseEvent(ArdougneCourseTracker.Event.RECOVERED, 4);
        assertFalse(gate.consumeHudOnlyXp(43, true, 1, 3,
            ArdougneCourseTracker.Event.NONE, T + 1));
    }

    @Test public void roofRecoveryAllowedButRealPositionMotionStillYellowAfterXp()
    {
        ArdougneFirstObstacleHudXp gate = new ArdougneFirstObstacleHudXp();
        ArdougneMotionTracker motion = new ArdougneMotionTracker();
        gate.onValidObstacleClick(0, 0, T);
        gate.observe(true, 1, 3, T + 1);
        motion.observe(true, 10, 10, 2672, 3295, 3, 5, 5, 123, T);
        assertTrue(gate.consumeHudOnlyXp(43, true, 1, 3,
            ArdougneCourseTracker.Event.NONE, T + 10_000_000L));
        motion.onConfirmedCourseXp(true, 15, 10, 2672, 3295, 3,
            5, 5, -1, T + 10_000_000L, 0);
        assertTrue("HUD is not permitted to claim stationary during genuine movement",
            motion.isMoving());
        motion.observe(true, 15, 10, 2672, 3295, 3, 5, 5, -1,
            T + 120_000_000L);
        assertFalse("only the old long hold is cleared", motion.isMoving());
    }

    @Test public void midFlightUnknownStageAndNewObstacleClickInvalidateTheClaim()
    {
        ArdougneFirstObstacleHudXp gate = new ArdougneFirstObstacleHudXp();
        gate.onValidObstacleClick(0, 0, T);
        gate.observe(true, -1, 2, T + 1);
        assertFalse(gate.consumeHudOnlyXp(43, true, 1, 3,
            ArdougneCourseTracker.Event.NONE, T + 2));
        gate.onValidObstacleClick(0, 0, T);
        gate.observe(true, 1, 3, T + 1);
        gate.onValidObstacleClick(1, 3, T + 2);
        assertFalse(gate.consumeHudOnlyXp(43, true, 1, 3,
            ArdougneCourseTracker.Event.NONE, T + 3));
    }
}

