package com.ardougnehelper;

import org.junit.Test;
import static org.junit.Assert.*;

public class ArdougneMarkPriorityTest
{
    private static final int THIRD = ArdougneMarkPriority.THIRD_OBSTACLE;
    private static final int FOURTH = ArdougneMarkPriority.FOURTH_OBSTACLE;

    private static boolean tick(ArdougneMarkPriority p, int stage, boolean movement,
        int count, int threshold, boolean scanValid, int gameTick)
    {
        return p.onTick(true, true, stage, movement, count, threshold, scanValid, gameTick);
    }

    private static ArdougneMarkPriority arriveAtFourthWithMarks(int count, int threshold)
    {
        ArdougneMarkPriority p = new ArdougneMarkPriority();
        p.onValidObstacleClick(THIRD, 10);
        tick(p, THIRD, true, count, threshold, true, 11);
        assertEquals(count >= threshold ? ArdougneMarkPriority.Mode.WAITING_FOR_LANDING :
            ArdougneMarkPriority.Mode.NORMAL, p.mode());
        p.onThirdObstacleCompleted();
        tick(p, FOURTH, false, count, threshold, true, 12);
        return p;
    }

    @Test public void validatedClickAloneDoesNotSuppressUntilMovementOrXp()
    {
        ArdougneMarkPriority p = new ArdougneMarkPriority();
        p.onValidObstacleClick(THIRD, 10);
        tick(p, THIRD, false, 4, 1, true, 10);
        assertFalse(p.suppressObstacleHulls());
        assertFalse(p.showExclusiveMarks());
        tick(p, THIRD, true, 4, 1, true, 11);
        assertTrue(p.suppressObstacleHulls());
        assertFalse(p.showExclusiveMarks()); // Marks are not yet reachable.
    }

    @Test public void xpWithoutSampledMovementStillOpensVerifiedWindow()
    {
        ArdougneMarkPriority p = new ArdougneMarkPriority();
        p.onValidObstacleClick(THIRD, 30);
        p.onThirdObstacleCompleted();
        tick(p, FOURTH, false, 1, 1, true, 31);
        assertTrue(p.showExclusiveMarks());
        assertTrue(p.suppressObstacleHulls());
    }

    @Test public void cannotEnterMarkModeWithoutConfirmedThirdInteraction()
    {
        ArdougneMarkPriority p = new ArdougneMarkPriority();
        tick(p, FOURTH, false, 12, 1, true, 30);
        assertFalse(p.suppressObstacleHulls());
        assertFalse(p.showExclusiveMarks());
        p.onThirdObstacleCompleted(); // No click/movement is registered.
        tick(p, FOURTH, false, 12, 1, true, 31);
        assertFalse(p.suppressObstacleHulls());
    }

    @Test public void thresholdLatchesUntilAllMarksDisappearTwice()
    {
        ArdougneMarkPriority p = arriveAtFourthWithMarks(3, 2);
        assertTrue(p.showExclusiveMarks());
        tick(p, FOURTH, false, 1, 2, true, 13);
        assertTrue("last mark must remain magenta below original threshold", p.showExclusiveMarks());
        tick(p, FOURTH, false, 0, 2, true, 14);
        assertTrue("first zero scan alone must not release", p.showExclusiveMarks());
        tick(p, FOURTH, false, 1, 2, true, 15);
        assertTrue(p.showExclusiveMarks());
        tick(p, FOURTH, false, 0, 2, true, 16);
        tick(p, FOURTH, false, 0, 2, true, 17);
        assertEquals(ArdougneMarkPriority.Mode.NORMAL, p.mode());
        assertFalse(p.suppressObstacleHulls());
    }

    @Test public void noMarkTraversalNeverSuppressesPreviewOrCurrentObstacle()
    {
        ArdougneMarkPriority p = new ArdougneMarkPriority();
        p.onValidObstacleClick(THIRD, 10);
        tick(p, THIRD, true, 0, 1, true, 11);
        assertEquals(ArdougneMarkPriority.Mode.NORMAL, p.mode());
        assertFalse("preview 4 must remain visible if there are no Marks", p.suppressObstacleHulls());
        p.onThirdObstacleCompleted();
        tick(p, FOURTH, false, 0, 1, true, 12);
        assertFalse(p.suppressObstacleHulls());
        tick(p, FOURTH, false, 0, 1, true, 13);
        assertFalse(p.suppressObstacleHulls());
    }

    @Test public void belowThresholdDoesNotHidePreviewButQualifyingMarkCanArriveLater()
    {
        ArdougneMarkPriority p = new ArdougneMarkPriority();
        p.onValidObstacleClick(THIRD, 10);
        tick(p, THIRD, true, 1, 2, true, 11);
        assertFalse(p.suppressObstacleHulls());
        p.onThirdObstacleCompleted();
        tick(p, FOURTH, false, 1, 2, true, 12);
        assertFalse(p.suppressObstacleHulls());
        tick(p, FOURTH, false, 2, 2, true, 13);
        assertTrue(p.suppressObstacleHulls());
        assertTrue(p.showExclusiveMarks());
    }

    @Test public void invalidSceneCannotCauseFalseCollectionCompletion()
    {
        ArdougneMarkPriority p = arriveAtFourthWithMarks(2, 2);
        for (int t = 13; t < 30; t++)
        {
            tick(p, FOURTH, false, 0, 2, false, t);
        }
        assertTrue(p.showExclusiveMarks());
        tick(p, FOURTH, false, 0, 2, true, 31);
        assertTrue(p.showExclusiveMarks());
        tick(p, FOURTH, false, 0, 2, true, 32);
        assertFalse(p.showExclusiveMarks());
    }

    @Test public void thresholdOneAndLateMarkStillAcquireWithinCollectionWindow()
    {
        ArdougneMarkPriority p = arriveAtFourthWithMarks(0, 1);
        tick(p, FOURTH, false, 0, 1, true, 13);
        assertEquals(ArdougneMarkPriority.Mode.NORMAL, p.mode());
        tick(p, FOURTH, false, 1, 1, true, 14);
        assertTrue(p.showExclusiveMarks());
        tick(p, FOURTH, false, 0, 1, true, 15);
        tick(p, FOURTH, false, 0, 1, true, 16);
        assertFalse(p.showExclusiveMarks());
    }

    @Test public void obstacleFourClickClosesWindowEvenIfNewMarkAppears()
    {
        ArdougneMarkPriority p = arriveAtFourthWithMarks(0, 1);
        tick(p, FOURTH, false, 0, 1, true, 13);
        p.onValidObstacleClick(FOURTH, 14);
        tick(p, FOURTH, true, 2, 1, true, 14);
        assertEquals(ArdougneMarkPriority.Mode.NORMAL, p.mode());
    }

    @Test public void stageExitAndDisabledSettingClearAllModes()
    {
        ArdougneMarkPriority p = arriveAtFourthWithMarks(2, 1);
        tick(p, FOURTH + 1, false, 2, 1, true, 13);
        assertFalse(p.suppressObstacleHulls());
        p = arriveAtFourthWithMarks(2, 1);
        p.onTick(false, true, FOURTH, false, 2, 1, true, 13);
        assertFalse(p.suppressObstacleHulls());
        p = arriveAtFourthWithMarks(2, 1);
        p.onTick(true, false, FOURTH, false, 2, 1, true, 13);
        assertFalse(p.suppressObstacleHulls());
    }

    @Test public void unconfirmedClickExpiresAndNeverOpensWindow()
    {
        ArdougneMarkPriority p = new ArdougneMarkPriority();
        p.onValidObstacleClick(THIRD, 4);
        tick(p, THIRD, false, 1, 1, true, 15);
        p.onThirdObstacleCompleted();
        tick(p, FOURTH, false, 1, 1, true, 16);
        assertFalse(p.suppressObstacleHulls());
    }

    @Test public void traversalTimeoutSignalsFallbackInsteadOfBlankForever()
    {
        ArdougneMarkPriority p = new ArdougneMarkPriority();
        p.onValidObstacleClick(THIRD, 0);
        tick(p, THIRD, true, 1, 1, true, 1);
        assertTrue(p.suppressObstacleHulls());
        assertFalse(tick(p, THIRD, true, 1, 1, true, 21));
        assertTrue(tick(p, THIRD, true, 1, 1, true, 22));
        assertFalse(p.suppressObstacleHulls());
    }

    @Test public void noMarksOutsideWindowEvenIfOtherStageHasMany()
    {
        ArdougneMarkPriority p = new ArdougneMarkPriority();
        for (int stage = 0; stage < ArdougneCourseTracker.STAGE_COUNT; stage++)
        {
            tick(p, stage, false, 15, 1, true, stage);
            assertFalse(p.showExclusiveMarks());
        }
    }
}

package com.ardougnehelper;

import org.junit.Test;
import static org.junit.Assert.*;

public class ArdougneMotionTrackerTest
{
    @Test public void localMovementAndHoldThenStationary()
    {
        ArdougneMotionTracker tracker = new ArdougneMotionTracker();
        tracker.observe(true, 10, 10, 100, 100, 0, 1, 1, -1, 1_000_000_000L);
        assertFalse(tracker.isMoving());
        tracker.observe(true, 14, 10, 100, 100, 0, 1, 1, -1, 1_050_000_000L);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 14, 10, 100, 100, 0, 1, 1, -1, 1_340_000_000L);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 14, 10, 100, 100, 0, 1, 1, -1, 1_401_000_000L);
        assertFalse(tracker.isMoving());
    }

    @Test public void roofObstacleAnimationAndWalkingPoseCountAsMovement()
    {
        ArdougneMotionTracker tracker = new ArdougneMotionTracker();
        tracker.observe(true, 10, 10, 100, 100, 3, 22, 11, -1, 100L);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 10, 10, 100, 100, 3, 11, 11, -1, 400_000_100L);
        assertTrue("temporary animation gaps must not flash grey", tracker.isMoving());
        tracker.observe(true, 10, 10, 100, 100, 3, 11, 11, -1, 1_200_000_100L);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 10, 10, 100, 100, 3, 11, 11, -1, 1_500_000_100L);
        assertFalse("stationary must eventually return", tracker.isMoving());
        tracker.observe(true, 10, 10, 100, 100, 3, 11, 11, 874, 1_510_000_100L);
        assertTrue(tracker.isMoving());
    }

    @Test public void worldTileChangesAndPlaneChangesIndicateMotion()
    {
        ArdougneMotionTracker tracker = new ArdougneMotionTracker();
        tracker.observe(true, 5, 5, 100, 100, 0, 10, 10, -1, 10L);
        tracker.observe(true, 5, 5, 101, 100, 0, 10, 10, -1, 20L);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 5, 5, 101, 100, 1, 10, 10, -1, 30L);
        assertTrue(tracker.isMoving());
    }

    @Test public void monotonicTimeCanBeNegative()
    {
        ArdougneMotionTracker tracker = new ArdougneMotionTracker();
        tracker.observe(true, 0, 0, 0, 0, 0, 2, 1, -1, -1_000_000_000L);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 0, 0, 0, 0, 0, 1, 1, -1, -800_000_000L);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 0, 0, 0, 0, 0, 1, 1, -1, -600_000_000L);
        assertFalse(tracker.isMoving());
    }

    @Test public void invalidSampleAndResetClearOldMovement()
    {
        ArdougneMotionTracker tracker = new ArdougneMotionTracker();
        tracker.observe(true, 10, 10, 100, 100, 0, 20, 10, -1, 10L);
        assertTrue(tracker.isMoving());
        tracker.observe(false, 10, 10, 100, 100, 0, 20, 10, -1, 11L);
        assertFalse(tracker.isMoving());
        tracker.observe(true, 10, 10, 100, 100, 0, 10, 10, -1, 12L);
        assertFalse(tracker.isMoving());
        tracker.reset();
        assertFalse(tracker.isMoving());
    }
    @Test public void rooftopLongAnimatedTraversalDoesNotFlashGreyAcrossTwoGameTicks()
    {
        ArdougneMotionTracker tracker = new ArdougneMotionTracker();
        tracker.observe(true, 12, 24, 200, 300, 3, 1, 1, 777, 5_000_000_000L);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 12, 24, 200, 300, 3, 1, 1, -1, 5_600_000_000L);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 12, 24, 200, 300, 3, 1, 1, -1, 6_199_000_000L);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 12, 24, 200, 300, 3, 1, 1, -1, 6_301_000_000L);
        assertFalse(tracker.isMoving());
    }

    @Test public void rooftopToGroundRetainsLastAnimationEvidenceTemporarily()
    {
        ArdougneMotionTracker tracker = new ArdougneMotionTracker();
        tracker.observe(true, 12, 24, 200, 300, 3, 5, 5, 888, 1_000_000_000L);
        tracker.observe(true, 50, 90, 201, 301, 0, 5, 5, -1, 1_600_000_000L);
        tracker.observe(true, 50, 90, 201, 301, 0, 5, 5, -1, 2_400_000_000L);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 50, 90, 201, 301, 0, 5, 5, -1, 2_901_000_000L);
        assertFalse(tracker.isMoving());
    }

    @Test public void confirmedTraversalRemainsYellowEvenWithoutAnimationId()
    {
        ArdougneMotionTracker tracker = new ArdougneMotionTracker();
        tracker.observe(true, 10, 10, 100, 100, 3, 5, 5, -1,
            1_000_000_000L, false);
        assertFalse(tracker.isMoving());
        tracker.observe(true, 10, 10, 100, 100, 3, 5, 5, -1,
            1_500_000_000L, true);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 10, 10, 100, 100, 3, 5, 5, -1,
            4_000_000_000L, true);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 10, 10, 100, 100, 3, 5, 5, -1,
            4_900_000_000L, false);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 10, 10, 100, 100, 3, 5, 5, -1,
            5_301_000_000L, false);
        assertFalse("bounded flight must not permanently stick yellow", tracker.isMoving());
    }


    @Test public void acceptedCourseXpCancelsOldYellowHoldImmediatelyWhenAlreadyIdle()
    {
        ArdougneMotionTracker tracker = new ArdougneMotionTracker();
        tracker.observe(true, 10, 10, 200, 300, 3, 5, 5, 777, 1_000_000_000L);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 10, 10, 200, 300, 3, 5, 5, -1, 1_100_000_000L);
        assertTrue("baseline rooftop hold remains active before XP", tracker.isMoving());
        tracker.onConfirmedCourseXp(true, 10, 10, 200, 300, 3,
            5, 5, -1, 1_110_000_000L);
        assertFalse("an accepted XP drop after the animation ends clears yellow now", tracker.isMoving());
        tracker.observe(true, 10, 10, 200, 300, 3, 5, 5, -1, 1_130_000_000L);
        assertFalse(tracker.isMoving());
    }

    @Test public void acceptedXpDoesNotClaimRestBeforeActorAnimationCompletes()
    {
        ArdougneMotionTracker tracker = new ArdougneMotionTracker();
        tracker.observe(true, 12, 24, 200, 300, 3, 5, 5, 987, 2_000_000_000L);
        tracker.onConfirmedCourseXp(true, 12, 24, 200, 300, 3,
            5, 5, 987, 2_010_000_000L);
        assertTrue("XP is completion evidence, not proof of no animation", tracker.isMoving());
        tracker.observe(true, 12, 24, 200, 300, 3, 5, 5, 988, 2_120_000_000L);
        assertTrue(tracker.isMoving());
        tracker.observe(true, 12, 24, 200, 300, 3, 5, 5, -1, 2_190_000_000L);
        assertTrue("short post-XP hold bridges small animation gaps", tracker.isMoving());
        tracker.observe(true, 12, 24, 200, 300, 3, 5, 5, -1, 2_221_000_000L);
        assertFalse("no extra 1.3-second rooftop delay", tracker.isMoving());
    }

    @Test public void acceptedFinalXpAtGroundClearsYellowToRedPlaneState()
    {
        ArdougneMotionTracker tracker = new ArdougneMotionTracker();
        tracker.observe(true, 12, 24, 200, 300, 3, 5, 5, 123, 1_000_000_000L);
        tracker.observe(true, 30, 40, 201, 300, 0, 5, 5, -1, 1_200_000_000L);
        assertTrue("normal final transition holds yellow until course XP", tracker.isMoving());
        tracker.onConfirmedCourseXp(true, 30, 40, 201, 300, 0,
            5, 5, -1, 1_210_000_000L);
        assertFalse(tracker.isMoving());
        assertEquals("ground HUD is derived from real plane, not XP quantity",
            ArdougneTauntHeader.GROUND_TEXT, ArdougneTauntHeader.textForState(0, tracker.isMoving()));
    }

    @Test public void acceptedFinalXpWhileStillOnRoofDoesNotForceGroundHud()
    {
        ArdougneMotionTracker tracker = new ArdougneMotionTracker();
        tracker.observe(true, 10, 10, 100, 100, 3, 5, 5, -1, 1_000_000_000L);
        tracker.onConfirmedCourseXp(true, 10, 10, 100, 100, 3,
            5, 5, -1, 1_010_000_000L);
        assertEquals("without real plane 0 the HUD cannot claim ground",
            ArdougneTauntHeader.ROOFTOP_TEXT, ArdougneTauntHeader.textForState(3, tracker.isMoving()));
    }

    @Test public void newMovementAfterConfirmedXpStillGetsNormalHold()
    {
        ArdougneMotionTracker tracker = new ArdougneMotionTracker();
        tracker.observe(true, 10, 10, 100, 100, 3, 5, 5, 800, 1_000_000_000L);
        tracker.onConfirmedCourseXp(true, 10, 10, 100, 100, 3,
            5, 5, -1, 1_010_000_000L);
        assertFalse(tracker.isMoving());
