package com.ardougnehelper;

import org.junit.Test;
import net.runelite.api.MenuAction;
import static org.junit.Assert.*;

public class ArdougnePluginTest
{
    @Test public void thresholdIsInclusive()
    {
        assertFalse(ArdougnePlugin.shouldHighlightMarks(0, 1));
        assertTrue(ArdougnePlugin.shouldHighlightMarks(1, 1));
        assertFalse(ArdougnePlugin.shouldHighlightMarks(2, 3));
        assertTrue(ArdougnePlugin.shouldHighlightMarks(3, 3));
        assertTrue(ArdougnePlugin.shouldHighlightMarks(5, 3));
    }

    @Test public void thresholdCannotBeZero()
    {
        assertFalse(ArdougnePlugin.shouldHighlightMarks(0, 0));
        assertTrue(ArdougnePlugin.shouldHighlightMarks(1, 0));
    }
    @Test public void onlyGenuineObjectActionsArmPreview()
    {
        assertTrue(ArdougnePlugin.isObstacleInteraction(MenuAction.GAME_OBJECT_FIRST_OPTION));
        assertTrue(ArdougnePlugin.isObstacleInteraction(MenuAction.GAME_OBJECT_FIFTH_OPTION));
        assertFalse(ArdougnePlugin.isObstacleInteraction(MenuAction.EXAMINE_OBJECT));
        assertFalse(ArdougnePlugin.isObstacleInteraction(MenuAction.GROUND_ITEM_FIRST_OPTION));
        assertFalse(ArdougnePlugin.isObstacleInteraction(MenuAction.WALK));
        assertFalse(ArdougnePlugin.isObstacleInteraction(MenuAction.CANCEL));
        assertFalse(ArdougnePlugin.isObstacleInteraction(null));
    }
}

package com.ardougnehelper;

import org.junit.Test;
import static org.junit.Assert.*;

public class ArdougnePreview5AuditTest
{
    @Test public void clickWithoutDepartureBeforeXpIsIdentified()
    {
        ArdougnePreview5Audit a = new ArdougnePreview5Audit();
        a.start(20);
        a.observeGate(true, false);
        a.observeRender(true, false, false, false, "NO_ACTIVE_GATE_OR_REGION");
        String summary = a.finish("28xp=ADVANCED", 21);
        assertTrue(summary.contains("verdict=DEPARTURE_GATE_NOT_CONFIRMED"));
        assertTrue(summary.contains("everPending=true"));
        assertTrue(summary.contains("onscreenFrames=0"));
    }

    @Test public void activeGateWithoutFollowingObjectIsDistinguished()
    {
        ArdougnePreview5Audit a = new ArdougnePreview5Audit();
        a.start(44);
        a.observeGate(false, true);
        a.observeRender(false, true, false, false, "FUTURE_OBJECT_MISSING");
        String summary = a.finish("28xp=ADVANCED", 46);
        assertTrue(summary.contains("verdict=PROJECTION_UNAVAILABLE"));
        assertTrue(summary.contains("FUTURE_OBJECT_MISSING=1"));
    }

    @Test public void offscreenPreviewIsDistinguishedFromNoShape()
    {
        ArdougnePreview5Audit a = new ArdougnePreview5Audit();
        a.start(15);
        a.observeGate(false, true);
        a.observeRender(false, true, true, false, "OFFSCREEN");
        String summary = a.finish("28xp=ADVANCED", 16);
        assertTrue(summary.contains("verdict=PROJECTED_OFFSCREEN"));
        assertTrue(summary.contains("offscreenFrames=1"));
    }

    @Test public void availablePreviewIsReportedWithoutChangingGate()
    {
        ArdougnePreview5Audit a = new ArdougnePreview5Audit();
        a.start(15);
        a.observeGate(false, true);
        a.observeRender(false, true, true, true, "ONSCREEN");
        a.observeRender(false, true, false, false, "MODEL_OR_CLICKBOX_UNAVAILABLE");
        String summary = a.finish("28xp=ADVANCED", 17);
        assertTrue(summary.contains("verdict=PREVIEW_RENDERED"));
        assertTrue(summary.contains("onscreenFrames=1"));
        assertTrue(summary.contains("MODEL_OR_CLICKBOX_UNAVAILABLE=1"));
    }

    @Test public void noFrameAfterClickIsRecorded()
    {
        ArdougnePreview5Audit a = new ArdougnePreview5Audit();
        a.start(1);
        a.observeGate(false, true);
        String summary = a.finish("28xp=ADVANCED", 2);
        assertTrue(summary.contains("verdict=NO_RENDER_FRAMES"));
    }

    @Test public void disabledAuditHasNoEffectOrReport()
    {
        ArdougnePreview5Audit a = new ArdougnePreview5Audit();
        a.observeGate(true, true);
        a.observeRender(true, true, true, true, "ONSCREEN");
        assertFalse(a.isTracking());
        assertNull(a.finish("xp", 1));
    }

    @Test public void restartingClearsOldAttemptEvidence()
    {
        ArdougnePreview5Audit a = new ArdougnePreview5Audit();
        a.start(10);
        a.observeRender(false, true, true, true, "ONSCREEN");
        a.start(20);
        a.observeGate(true, false);
        assertFalse(a.finish("xp", 21).contains("PREVIEW_RENDERED"));
    }
}

package com.ardougnehelper;

