        gate.onValidObstacleClick(0, 0, 21, 2670, 3290, 0);
        assertTrue(gate.isPendingFor(0));
        assertFalse(gate.isActiveFor(0));
        gate.onTick(0, 22, 2670, 3290, 0);
        assertFalse(gate.isActiveFor(0));
        gate.onTick(0, 23, 2670, 3291, 0);
        assertTrue(gate.isActiveFor(0));
        assertFalse(gate.isPendingFor(0));
    }

    @Test public void ignoresWrongStageClicks()
    {
        ArdougnePreviewGate gate = new ArdougnePreviewGate();
        gate.onValidObstacleClick(2, 1, 20, 2664, 3318, 3);
        gate.onTick(1, 21, 2665, 3318, 3);
        assertFalse(gate.isActiveFor(1));
        assertFalse(gate.isPendingFor(1));
    }

    @Test public void expiresIfPlayerNeverStartsMoving()
    {
        ArdougnePreviewGate gate = new ArdougnePreviewGate();
        gate.onValidObstacleClick(1, 1, 20, 2665, 3318, 3);
        gate.onTick(1, 20 + ArdougnePreviewGate.MAX_CONFIRM_TICKS, 2665, 3318, 3);
        assertTrue(gate.isPendingFor(1));
        gate.onTick(1, 21 + ArdougnePreviewGate.MAX_CONFIRM_TICKS, 2666, 3318, 3);
        assertFalse(gate.isActiveFor(1));
        assertFalse(gate.isPendingFor(1));
    }

    @Test public void clearsOnXpStageAdvance()
    {
        ArdougnePreviewGate gate = new ArdougnePreviewGate();
        gate.onValidObstacleClick(0, 0, 10, 2670, 3290, 0);
        gate.onTick(0, 11, 2670, 3291, 0);
        assertTrue(gate.isActiveFor(0));
        gate.onTick(1, 12, 2671, 3299, 3);
        assertFalse(gate.isActiveFor(0));
        assertFalse(gate.isActiveFor(1));
    }

    @Test public void resetAfterFallLapOrTeleport()
    {
        ArdougnePreviewGate gate = new ArdougnePreviewGate();
        for (int stage : new int[]{2, 6, 0})
        {
            gate.onValidObstacleClick(stage, stage, 50, 2655, 3305, 3);
            gate.onTick(stage, 51, 2655, 3306, 3);
            assertTrue(gate.isActiveFor(stage));
            gate.reset();
            assertFalse(gate.isActiveFor(stage));
        }
    }

    @Test public void switchingToAnotherStageCancelsPending()
    {
        ArdougnePreviewGate gate = new ArdougnePreviewGate();
        gate.onValidObstacleClick(4, 4, 5, 2651, 3309, 3);
        gate.onTick(5, 6, 2652, 3309, 3);
        assertFalse(gate.isPendingFor(4));
        assertFalse(gate.isActiveFor(4));
        assertFalse(gate.isActiveFor(5));
    }

    @Test public void reClickDoesNotBlankAlreadyActivePreview()
    {
        ArdougnePreviewGate gate = new ArdougnePreviewGate();
        gate.onValidObstacleClick(1, 1, 5, 2665, 3318, 3);
        gate.onTick(1, 6, 2666, 3318, 3);
        gate.onValidObstacleClick(1, 1, 7, 2666, 3318, 3);
        assertTrue(gate.isActiveFor(1));
    }

    @Test public void transitionThroughUnknownStageClearsGate()
    {
        ArdougnePreviewGate gate = new ArdougnePreviewGate();
        gate.onValidObstacleClick(6, 6, 1, 2660, 3300, 3);
        gate.onTick(6, 2, 2660, 3301, 3);
        gate.onTick(-1, 3, 2660, 3302, 0);
        assertFalse(gate.isActiveFor(6));
    }
    @Test public void obstacleFiveToSixArmsOnClientTickAnimationBeforeWorldMovement()
    {
        ArdougnePreviewGate gate = new ArdougnePreviewGate();
        gate.onValidObstacleClick(4, 4, 50, 2651, 3309, 3,
            300, 400, -1, 1, 1);
        gate.onClientActivity(4, 50, 2651, 3309, 3,
            300, 400, -1, 1, 1);
        assertFalse("click alone must not arm preview 6", gate.isActiveFor(4));
        gate.onClientActivity(4, 50, 2651, 3309, 3,
            300, 400, 993, 1, 1);
        assertTrue("animation start permits preview 6 before the XP arrives", gate.isActiveFor(4));
        gate.onTick(4, 51, 2651, 3309, 3);
        assertTrue(gate.isActiveFor(4));
        gate.onTick(5, 52, 2656, 3297, 3);
        assertFalse("XP stage change resets the previous preview", gate.isActiveFor(4));
    }

    @Test public void clientTickSubtilePositionChangeCanActivatePreviewFour()
    {
        ArdougnePreviewGate gate = new ArdougnePreviewGate();
        gate.onValidObstacleClick(2, 2, 10, 2656, 3318, 3,
            900, 800, -1, 3, 3);
        gate.onClientActivity(2, 10, 2656, 3318, 3,
            902, 800, -1, 3, 3);
        assertTrue("subtile movement avoids the 600 ms timing gap", gate.isActiveFor(2));
    }

    @Test public void ongoingAnimationAtClickIsNotFreshActivity()
    {
        ArdougnePreviewGate gate = new ArdougnePreviewGate();
        gate.onValidObstacleClick(4, 4, 10, 2651, 3309, 3,
            10, 20, 1000, 43, 42);
        gate.onClientActivity(4, 10, 2651, 3309, 3,
            10, 20, 1000, 43, 42);
        assertFalse("pre-existing animation cannot authorize a new preview", gate.isActiveFor(4));
        gate.onClientActivity(4, 10, 2651, 3309, 3,
            10, 20, 1001, 43, 42);
        assertTrue(gate.isActiveFor(4));
    }

    @Test public void clientActivityDoesNotBypassExpiryOrWrongStage()
    {
        ArdougnePreviewGate gate = new ArdougnePreviewGate();
        gate.onValidObstacleClick(4, 4, 10, 2651, 3309, 3,
            10, 20, -1, 11, 11);
        gate.onClientActivity(4, 21, 2651, 3309, 3,
            11, 20, 871, 11, 11);
        assertFalse(gate.isActiveFor(4));
        gate.onValidObstacleClick(4, 4, 22, 2651, 3309, 3,
            10, 20, -1, 11, 11);
        gate.onClientActivity(5, 22, 2651, 3309, 3,
            11, 20, 871, 11, 11);
        assertFalse(gate.isActiveFor(4));
        assertFalse(gate.isActiveFor(5));
    }

    @Test public void confirmedTraversalActivityIsBoundedAndStopsAfterStageAdvance()
    {
        ArdougnePreviewGate gate = new ArdougnePreviewGate();
        gate.onValidObstacleClick(4, 4, 10, 2651, 3309, 3,
            10, 20, -1, 5, 5);
        assertFalse(gate.isInFlightFor(4, 10));
        gate.onClientActivity(4, 11, 2651, 3309, 3,
            10, 20, 999, 5, 5);
        assertTrue(gate.isInFlightFor(4, 11));
        assertTrue(gate.isInFlightFor(4, 11 + ArdougnePreviewGate.MAX_IN_FLIGHT_TICKS));
        assertFalse(gate.isInFlightFor(4, 12 + ArdougnePreviewGate.MAX_IN_FLIGHT_TICKS));
        assertFalse(gate.isInFlightFor(5, 11));
        gate.onTick(5, 13, 2656, 3297, 3);
        assertFalse(gate.isInFlightFor(4, 13));
    }

    @Test public void confirmedButUnfinishedTraversalRestoresCyanAfterBound()
    {
        ArdougnePreviewGate gate = new ArdougnePreviewGate();
        gate.onValidObstacleClick(4, 4, 10, 2651, 3309, 3,
            10, 20, -1, 5, 5);
        gate.onClientActivity(4, 11, 2651, 3309, 3,
            20, 20, -1, 5, 5);
        assertTrue(gate.isActiveFor(4));
        gate.onTick(4, 11 + ArdougnePreviewGate.MAX_IN_FLIGHT_TICKS,
            2651, 3309, 3);
        assertTrue(gate.isActiveFor(4));
        gate.onTick(4, 12 + ArdougnePreviewGate.MAX_IN_FLIGHT_TICKS,
            2651, 3309, 3);
        assertFalse(gate.isActiveFor(4));
    }

}

package com.ardougnehelper;

import org.junit.Test;
import static org.junit.Assert.*;

public class ArdougnePreviewPlanTest
{
    @Test public void ghostAlwaysLooksOneStageAheadOfTheCyanHull()
    {
        int count = ArdougneCourseTracker.STAGE_COUNT;
        for (int selected = 0; selected < count; selected++)
        {
            int orange = ArdougnePreviewPlan.followingStage(selected);
            assertEquals((selected + 1) % count, orange);
            assertNotEquals(selected, orange);
        }
    }

    @Test public void previewWrapsAfterFinalGapToWoodenBeams()
    {
        assertEquals(0, ArdougnePreviewPlan.followingStage(6));
        assertEquals(1, ArdougnePreviewPlan.followingStage(0));
    }

