        assertEquals(-1, ArdougnePreviewPlan.followingStage(7));
    }
}

package com.ardougnehelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.image.BufferedImage;
import org.junit.Test;
import static org.junit.Assert.*;

public class ArdougneTauntHeaderTest
{
    @Test public void exactMessagesAndSupportedPlanes()
    {
        assertEquals("Don't give up!", ArdougneTauntHeader.textForPlane(0));
        for (int p = 1; p <= 3; p++)
        {
            assertEquals("Isn't this fun?", ArdougneTauntHeader.textForPlane(p));
        }
        assertNull(ArdougneTauntHeader.textForPlane(-1));
        assertNull(ArdougneTauntHeader.textForPlane(4));
    }

    @Test public void movementOverridesBothGroundAndRooftopWithOpaqueYellow()
    {
        for (int plane = 0; plane <= 3; plane++)
        {
            assertEquals("I believe in you!", ArdougneTauntHeader.textForState(plane, true));
            BufferedImage image = paint(plane, true);
            assertEquals(ArdougneTauntHeader.MOVING_COLOR.getRGB(), image.getRGB(10, 6));
            assertEquals(255, (image.getRGB(10, 6) >>> 24));
        }
        assertNull(ArdougneTauntHeader.textForState(-1, true));
    }

    @Test public void groundHeaderIsOpaqueRedOutsideTextEvenWithTransparentCanvas()
    {
        BufferedImage image = paint(0);
        assertEquals(new Color(255, 0, 0, 255).getRGB(), image.getRGB(10, 6));
        assertEquals(255, (image.getRGB(10, 6) >>> 24));
    }

    @Test public void rooftopHeaderLeavesBackgroundUnpaintedForPanelOpacity()
    {
        for (int plane = 1; plane <= 3; plane++)
        {
            BufferedImage image = paint(plane);
            assertEquals("Rooftop header must use existing panel background", 0, image.getRGB(10, 6) >>> 24);
        }
    }

    @Test public void unknownPlaneDoesNotDraw()
    {
        BufferedImage image = paint(-1);
        assertEquals(0, image.getRGB(10, 6) >>> 24);
    }

    private static BufferedImage paint(int plane)
    {
        return paint(plane, false);
    }

    private static BufferedImage paint(int plane, boolean moving)
    {
        BufferedImage image = new BufferedImage(140, 55, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try
        {
            ArdougneTauntHeader header = new ArdougneTauntHeader(plane, moving);
            header.setPreferredLocation(new Point(4, 4));
            header.setPreferredSize(new Dimension(121, 0));
            header.render(graphics);
        }
        finally
        {
            graphics.dispose();
        }
        return image;
    }
}

package com.ardougnehelper;

import org.junit.Test;
import static org.junit.Assert.*;

/** Regression timelines for the course overlay transitions. */
public class ArdougneVisualFlowTest
{
    @Test public void thirdToFourthWithNoMarksKeepsOrangeUntilStageChanges()
    {
        ArdougnePreviewGate preview = new ArdougnePreviewGate();
        ArdougneMarkPriority priority = new ArdougneMarkPriority();
        preview.onValidObstacleClick(2, 2, 10, 2656, 3318, 3,
            1000, 2000, -1, 5, 5);
        priority.onValidObstacleClick(2, 10);
        preview.onClientActivity(2, 10, 2656, 3318, 3,
            1012, 2000, -1, 5, 5);
        assertTrue(preview.isActiveFor(2));
        priority.onTick(true, true, 2, preview.isActiveFor(2), 0, 1, true, 11);
        assertFalse("empty third landing must not suppress preview 4", priority.suppressObstacleHulls());
        priority.onThirdObstacleCompleted();
        preview.reset();
        priority.onTick(true, true, 3, false, 0, 1, true, 12);
        assertFalse("current obstacle 4 must show cyan after XP", priority.suppressObstacleHulls());
    }

    @Test public void thirdToFourthWithMarksShowsOnlyMagentaUntilTheyAllDisappear()
    {
        ArdougnePreviewGate preview = new ArdougnePreviewGate();
        ArdougneMarkPriority priority = new ArdougneMarkPriority();
        preview.onValidObstacleClick(2, 2, 10, 2656, 3318, 3,
            1000, 2000, -1, 5, 5);
        priority.onValidObstacleClick(2, 10);
        preview.onClientActivity(2, 10, 2656, 3318, 3,
            1012, 2000, -1, 5, 5);
        priority.onTick(true, true, 2, preview.isActiveFor(2), 3, 2, true, 11);
        assertTrue("qualifying Mark suppresses preview 4", priority.suppressObstacleHulls());
        assertFalse("no premature magenta before stage 4", priority.showExclusiveMarks());
        priority.onThirdObstacleCompleted();
        preview.reset();
        priority.onTick(true, true, 3, false, 3, 2, true, 12);
        assertTrue(priority.showExclusiveMarks());
        priority.onTick(true, true, 3, false, 1, 2, true, 13);
        assertTrue("keep highlighting last Mark below threshold", priority.showExclusiveMarks());
        priority.onTick(true, true, 3, false, 0, 2, true, 14);
        assertTrue(priority.showExclusiveMarks());
        priority.onTick(true, true, 3, false, 0, 2, true, 15);
        assertFalse(priority.suppressObstacleHulls());
    }

    @Test public void fifthToSixthAnimationOnClientTickAuthorizesOrangePreview()
    {
        ArdougnePreviewGate preview = new ArdougnePreviewGate();
        ArdougneMarkPriority priority = new ArdougneMarkPriority();
        preview.onValidObstacleClick(4, 4, 20, 2651, 3309, 3,
            1200, 1000, -1, 5, 5);
        preview.onClientActivity(4, 20, 2651, 3309, 3,
            1200, 1000, 1234, 5, 5);
        priority.onTick(true, true, 4, false, 5, 1, true, 20);
        assertTrue("preview 6 gate must open without waiting for world-tile update", preview.isActiveFor(4));
        assertFalse("Marks cannot suppress obstacle-6 preview", priority.suppressObstacleHulls());
    }
}
